import http.server, json, sys, os, threading, time
LOG = os.environ.get('MOCK_LOG', '/tmp/mock/log.txt')
RESP = os.environ.get('MOCK_RESP', '/tmp/mock/resp.py')
class H(http.server.BaseHTTPRequestHandler):
    protocol_version = 'HTTP/1.1'
    def handle_any(self):
        n = int(self.headers.get('Content-Length') or 0)
        body = self.rfile.read(n) if n else b''
        with open(LOG, 'a') as f:
            f.write('==== %s %s\n' % (self.command, self.path))
            for k, v in self.headers.items():
                f.write('%s: %s\n' % (k, v))
            f.write('\n' + body.decode('utf-8', 'replace') + '\n')
        status, headers, rbody = 200, {'Content-Type': 'application/x-amz-json-1.1'}, b'{}'
        try:
            ns = {}
            exec(open(RESP).read(), ns)
            r = ns['respond'](self.command, self.path, dict(self.headers), body)
            if r is not None:
                status, headers, rbody = r
                if isinstance(rbody, str): rbody = rbody.encode()
        except Exception as e:
            with open(LOG, 'a') as f: f.write('RESP ERROR %r\n' % e)
        self.send_response(status)
        for k, v in headers.items():
            self.send_header(k, v)
        self.send_header('Content-Length', str(len(rbody)))
        self.end_headers()
        self.wfile.write(rbody)
    do_GET = do_POST = do_PUT = do_DELETE = do_HEAD = handle_any
    def log_message(self, *a): pass
port = int(sys.argv[1]) if len(sys.argv) > 1 else 9999
http.server.ThreadingHTTPServer(('127.0.0.1', port), H).serve_forever()
