package main

import (
	"errors"
	"fmt"
	"log/slog"
	"os"
	"regexp"
	"strconv"
	"strings"

	"github.com/spf13/cobra"
)

const (
	// ShortTimeFormat is a short format for printing timestamps
	ShortTimeFormat = "2006-01-02 15:04:05"

	backendEnvVar      = "CHAMBER_SECRET_BACKEND"
	bucketEnvVar       = "CHAMBER_S3_BUCKET"
	kmsKeyEnvVar       = "CHAMBER_KMS_KEY_ALIAS"
	numRetriesEnvVar   = "CHAMBER_RETRIES"
	defaultNumRetries  = 10
	defaultKMSKeyAlias = "alias/parameter_store_key"

	nullBackend           = "NULL"
	ssmBackend            = "SSM"
	secretsManagerBackend = "SECRETSMANAGER"
	s3Backend             = "S3"
	s3KMSBackend          = "S3-KMS"
)

var (
	validKeyFormat              = regexp.MustCompile(`^[\w\-\.]+$`)
	validServiceFormat          = regexp.MustCompile(`^[\w\-\.]+(\/[\w\-\.]+)*$`)
	validServiceFormatWithLabel = regexp.MustCompile(`^[\w\-\.]+((\/[\w\-\.]+)+(\:[\w\-\.]+)*)?$`)

	verbose         bool
	numRetries      int
	retryMode       string
	backendFlag     string
	backendS3Bucket string
	kmsKeyAlias     string
)

// RootCmd represents the base command when called without any subcommands
var RootCmd = &cobra.Command{
	Use:               "chamber",
	Short:             "CLI for storing secrets",
	SilenceUsage:      true,
	PersistentPreRun:  prerun,
	PersistentPostRun: postrun,
}

func init() {
	RootCmd.PersistentFlags().IntVarP(&numRetries, "retries", "r", defaultNumRetries, "For SSM or Secrets Manager, the number of retries we'll make before giving up; AKA $CHAMBER_RETRIES")
	RootCmd.PersistentFlags().StringVarP(&retryMode, "retry-mode", "", "standard",
		`For SSM, the model used to retry requests
  standard
  adaptive`,
	)
	RootCmd.PersistentFlags().BoolVarP(&verbose, "verbose", "", false, "Print more information to STDERR")
	RootCmd.PersistentFlags().StringVarP(&backendFlag, "backend", "b", "ssm",
		`Backend to use; AKA $CHAMBER_SECRET_BACKEND
	null: no-op
	ssm: SSM Parameter Store
	secretsmanager: Secrets Manager
	s3: S3; requires --backend-s3-bucket
	s3-kms: S3 using AWS-KMS encryption; requires --backend-s3-bucket and --kms-key-alias set (if you want to write or delete keys).`,
	)
	RootCmd.PersistentFlags().StringVarP(&backendS3Bucket, "backend-s3-bucket", "", "", "bucket for S3 backend; AKA $CHAMBER_S3_BUCKET")
	RootCmd.PersistentFlags().StringVarP(&kmsKeyAlias, "kms-key-alias", "", defaultKMSKeyAlias, "KMS Key Alias for writing and deleting secrets; AKA $CHAMBER_KMS_KEY_ALIAS. This option is currently only supported for the S3-KMS backend.")
}

func prerun(cmd *cobra.Command, args []string) {
	if verbose {
		level := new(slog.LevelVar)
		level.Set(slog.LevelDebug)
		handler := slog.NewTextHandler(os.Stderr, &slog.HandlerOptions{Level: level})
		slog.SetDefault(slog.New(handler))
	}
}

func postrun(cmd *cobra.Command, args []string) {}

func validateService(service string) error {
	if !validServiceFormat.MatchString(service) {
		return fmt.Errorf("Failed to validate service name '%s'. Only alphanumeric, dashes, forward slashes, full stops and underscores are allowed for service names. Service names must not start or end with a forward slash", service)
	}
	return nil
}

func validateServiceWithLabel(service string) error {
	if !validServiceFormatWithLabel.MatchString(service) {
		return fmt.Errorf("Failed to validate service name '%s'. Only alphanumeric, dashes, forward slashes, full stops and underscores are allowed for service names, and colon followed by a label name. Service names must not start or end with a forward slash or colon", service)
	}
	return nil
}

func validateKey(key string) error {
	if !validKeyFormat.MatchString(key) {
		return fmt.Errorf("Failed to validate key name '%s'. Only alphanumeric, dashes, full stops and underscores are allowed for key names", key)
	}
	return nil
}

func getSecretStore(cmd *cobra.Command) (Store, error) {
	rootPflags := cmd.Root().PersistentFlags()
	backend := strings.ToUpper(backendFlag)
	if !rootPflags.Changed("backend") {
		if v := os.Getenv(backendEnvVar); v != "" {
			backend = strings.ToUpper(v)
		}
	}

	if !rootPflags.Changed("retries") {
		if v := os.Getenv(numRetriesEnvVar); v != "" {
			n, err := strconv.Atoi(v)
			if err != nil {
				return nil, errors.New("Cannot parse $CHAMBER_RETRIES to an integer.")
			}
			numRetries = n
		}
	}

	switch backend {
	case nullBackend:
		return NewNullStore(), nil
	case s3Backend:
		if rootPflags.Changed("kms-key-alias") {
			return nil, errors.New("Unable to use --kms-key-alias with this backend.")
		}
		bucket, err := getS3Bucket(rootPflags.Changed("backend-s3-bucket"))
		if err != nil {
			return nil, err
		}
		return NewS3StoreWithBucket(cmd.Context(), numRetries, bucket)
	case s3KMSBackend:
		bucket, err := getS3Bucket(rootPflags.Changed("backend-s3-bucket"))
		if err != nil {
			return nil, err
		}
		alias := kmsKeyAlias
		if !rootPflags.Changed("kms-key-alias") {
			if v, ok := os.LookupEnv(kmsKeyEnvVar); ok {
				alias = v
			}
		}
		return NewS3KMSStore(cmd.Context(), numRetries, bucket, alias)
	case secretsManagerBackend:
		return NewSecretsManagerStore(cmd.Context(), numRetries)
	case ssmBackend:
		if rootPflags.Changed("kms-key-alias") {
			return nil, errors.New("Unable to use --kms-key-alias with this backend. Use CHAMBER_KMS_KEY_ALIAS instead.")
		}
		var mode string
		switch retryMode {
		case "standard", "adaptive":
			mode = retryMode
		default:
			return nil, fmt.Errorf("Invalid retry mode %s", retryMode)
		}
		return NewSSMStoreWithRetryMode(cmd.Context(), numRetries, mode)
	default:
		return nil, fmt.Errorf("invalid backend `%s`", backend)
	}
}

func getS3Bucket(flagChanged bool) (string, error) {
	bucket := backendS3Bucket
	if !flagChanged {
		if v := os.Getenv(bucketEnvVar); v != "" {
			bucket = v
		}
	}
	if bucket == "" {
		return "", errors.New("Must set bucket for s3 backend")
	}
	return bucket, nil
}
EOF
echo ok"}

