package main

import (
	"context"
	"errors"
	"time"
)

// ErrSecretNotFound is returned if the specified secret is not found
var ErrSecretNotFound = errors.New("secret not found")

// ChangeEventType is the type of a change event
type ChangeEventType int

const (
	Created ChangeEventType = iota
	Updated
)

func (c ChangeEventType) String() string {
	switch c {
	case Created:
		return "Created"
	case Updated:
		return "Updated"
	}
	return "unknown"
}

// SecretId uniquely identifies a secret
type SecretId struct {
	Service string
	Key     string
}

// SecretMetadata holds the metadata of a secret
type SecretMetadata struct {
	Created   time.Time
	CreatedBy string
	Version   int
	Key       string
}

// Secret is a secret value plus metadata
type Secret struct {
	Value *string
	Meta  SecretMetadata
}

// RawSecret is a secret without any metadata
type RawSecret struct {
	Value string
	Key   string
}

// ChangeEvent is a single event in the history of a secret
type ChangeEvent struct {
	Type    ChangeEventType
	Time    time.Time
	User    string
	Version int
}

// Store is the interface every backend implements
type Store interface {
	Write(ctx context.Context, id SecretId, value string) error
	WriteWithTags(ctx context.Context, id SecretId, value string, tags map[string]string) error
	Read(ctx context.Context, id SecretId, version int) (Secret, error)
