	listCmd.Flags().BoolVarP(&byTime, "time", "t", false, "Sort by modified time")
	listCmd.Flags().BoolVarP(&byUser, "user", "u", false, "Sort by user")
	listCmd.Flags().BoolVarP(&byVersion, "version", "v", false, "Sort by version")
	RootCmd.AddCommand(listCmd)
}

func list(cmd *cobra.Command, args []string) error {
	service := normalizeService(args[0])
	if err := validateServiceWithLabel(service); err != nil {
		return fmt.Errorf("Failed to validate service: %w", err)
	}

	secretStore, err := getSecretStore(cmd)
	if err != nil {
		return fmt.Errorf("Failed to get secret store: %w", err)
	}
	secrets, err := secretStore.List(cmd.Context(), service, withValues)
	if err != nil {
		return fmt.Errorf("Failed to list store contents: %w", err)
	}

	w := tabwriter.NewWriter(os.Stdout, 0, 8, 2, '\t', 0)
	fmt.Fprint(w, "Key\tVersion\tLastModified\tUser")
	if withValues {
		fmt.Fprint(w, "\tValue")
	}
	fmt.Fprintln(w, "")

	sort.SliceStable(secrets, func(i, j int) bool { return secrets[i].Meta.Key < secrets[j].Meta.Key })
	switch {
	case byTime:
		sort.SliceStable(secrets, func(i, j int) bool { return secrets[i].Meta.Created.Before(secrets[j].Meta.Created) })
	case byUser:
		sort.SliceStable(secrets, func(i, j int) bool { return secrets[i].Meta.CreatedBy < secrets[j].Meta.CreatedBy })
	case byVersion:
		sort.SliceStable(secrets, func(i, j int) bool { return secrets[i].Meta.Version < secrets[j].Meta.Version })
	}

	for _, secret := range secrets {
		fmt.Fprintf(w, "%s\t%d\t%s\t%s",
			key(secret.Meta.Key),
			secret.Meta.Version,
			secret.Meta.Created.Local().Format(ShortTimeFormat),
			secret.Meta.CreatedBy)
		if withValues {
			value := ""
			if secret.Value != nil {
				value = *secret.Value
			}
			fmt.Fprintf(w, "\t%s", value)
		}
		fmt.Fprintln(w, "")
	}

	w.Flush()
	return nil
}
