package main

import (
	"bufio"
	"encoding/csv"
	"encoding/json"
	"fmt"
	"io"
	"os"
	"strings"

	"github.com/spf13/cobra"
)

var (
	exportFormat string
	exportOutput string
)

var exportCmd = &cobra.Command{
	Use:   "export <service...>",
	Short: "Exports parameters in the specified format",
	Args:  cobra.MinimumNArgs(1),
	RunE:  runExport,
}

func init() {
	exportCmd.Flags().SortFlags = false
	exportCmd.Flags().StringVarP(&exportFormat, "format", "f", "json", "Output format (json, yaml, java-properties, csv, tsv, dotenv, tfvars)")
	exportCmd.Flags().StringVarP(&exportOutput, "output-file", "o", "", "Output file (default is standard output)")
	RootCmd.AddCommand(exportCmd)
}

func runExport(cmd *cobra.Command, args []string) error {
	var err error

	secretStore, err := getSecretStore(cmd)
	if err != nil {
		return err
	}
	params := make(map[string]string)
	for _, service := range args {
		service = normalizeService(service)
		if err := validateService(service); err != nil {
			return fmt.Errorf("Failed to validate service %s: %w", service, err)
		}

		rawSecrets, err := secretStore.ListRaw(cmd.Context(), service)
		if err != nil {
			return fmt.Errorf("Failed to list store contents: %w", err)
		}
		for _, rawSecret := range rawSecrets {
			k := key(rawSecret.Key)
			if _, ok := params[k]; ok {
				fmt.Fprintf(os.Stderr, "warning: parameter %s specified more than once (overridden by service %s)\n", k, service)
			}
			params[k] = rawSecret.Value
		}
	}

	file := os.Stdout
	if exportOutput != "" {
		if file, err = os.OpenFile(exportOutput, os.O_CREATE|os.O_WRONLY|os.O_TRUNC, 0644); err != nil {
			return fmt.Errorf("Failed to open output file for writing: %w", err)
		}
		defer file.Close()
		defer file.Sync()
	}
	w := bufio.NewWriter(file)
	defer w.Flush()

	switch strings.ToLower(exportFormat) {
	case "json":
		err = exportAsJson(params, w)
	case "yaml":
		err = exportAsYaml(params, w)
	case "java-properties", "properties":
		err = exportAsJavaProperties(params, w)
	case "csv":
		err = exportAsCsv(params, w)
	case "tsv":
		err = exportAsTsv(params, w)
	case "dotenv":
		err = exportAsDotenv(params, w)
	case "tfvars":
		err = exportAsTFvars(params, w)
	default:
		err = fmt.Errorf("Unsupported export format: %s", exportFormat)
	}

	if err != nil {
		return fmt.Errorf("Unable to export parameters: %w", err)
	}

	return nil
}

func exportAsJson(params map[string]string, w io.Writer) error {
	return json.NewEncoder(w).Encode(params)
}

func exportAsYaml(params map[string]string, w io.Writer) error {
	_, err := io.WriteString(w, yamlEncodeStringMap(params))
	return err
}

func exportAsJavaProperties(params map[string]string, w io.Writer) error {
	for _, k := range sortedKeys(params) {
		if _, err := fmt.Fprintf(w, "%s = %s\n", propertiesEncode(k, " :"), propertiesEncode(params[k], "")); err != nil {
			return err
		}
	}
	return nil
}

func exportAsCsv(params map[string]string, w io.Writer) error {
	csvWriter := csv.NewWriter(w)
	defer csvWriter.Flush()
	for _, k := range sortedKeys(params) {
		if err := csvWriter.Write([]string{k, params[k]}); err != nil {
			return fmt.Errorf("Failed to write param %s to CSV file: %w", k, err)
		}
	}
	return nil
}

func exportAsTsv(params map[string]string, w io.Writer) error {
	csvWriter := csv.NewWriter(w)
	csvWriter.Comma = '\t'
	defer csvWriter.Flush()
	for _, k := range sortedKeys(params) {
		if err := csvWriter.Write([]string{k, params[k]}); err != nil {
			return fmt.Errorf("Failed to write param %s to TSV file: %w", k, err)
		}
	}
	return nil
}

func exportAsDotenv(params map[string]string, w io.Writer) error {
	var b strings.Builder
	for _, k := range sortedKeys(params) {
		name := envVarName(k, false)
		if err := validateShellName(name); err != nil {
			return err
		}
		fmt.Fprintf(&b, "%s=\"%s\"\n", name, doubleQuoteEscape(params[k]))
	}
	_, err := io.WriteString(w, b.String())
	return err
}

func exportAsTFvars(params map[string]string, w io.Writer) error {
	var b strings.Builder
	for _, k := range sortedKeys(params) {
		name := strings.ReplaceAll(strings.ReplaceAll(k, "-", "_"), ".", "_")
		fmt.Fprintf(&b, "%s = \"%s\"\n", name, doubleQuoteEscape(params[k]))
	}
	_, err := io.WriteString(w, b.String())
	return err
}

// propertiesEncode encodes a string the way java properties files expect
// (ISO-8859-1 with unicode escapes)
func propertiesEncode(s string, special string) string {
	var b strings.Builder
	for _, r := range s {
		switch {
		case r < 1<<8:
			switch r {
			case '\f':
				b.WriteString(`\f`)
			case '\n':
				b.WriteString(`\n`)
			case '\r':
				b.WriteString(`\r`)
			case '\t':
				b.WriteString(`\t`)
			case '\\':
				b.WriteString(`\\`)
			default:
				if strings.ContainsRune(special, r) {
					b.WriteString(`\`)
				}
				b.WriteRune(r)
			}
		case r < 1<<16:
			fmt.Fprintf(&b, "\\u%04x", r)
		default:
			b.WriteString("?")
		}
	}
	return b.String()
}
EOF
echo ok"}

