func validateServiceAndKey(serviceArg, keyArg string) (string, string, error) {
	service := normalizeService(serviceArg)
	if err := validateService(service); err != nil {
		return "", "", fmt.Errorf("Failed to validate service: %w", err)
	}
	k := normalizeKey(keyArg)
	if err := validateKey(k); err != nil {
		return "", "", fmt.Errorf("Failed to validate key: %w", err)
	}
	return service, k, nil
}

func tagRead(cmd *cobra.Command, args []string) error {
	service, k, err := validateServiceAndKey(args[0], args[1])
	if err != nil {
		return err
	}

	secretStore, err := getSecretStore(cmd)
	if err != nil {
		return fmt.Errorf("Failed to get secret store: %w", err)
	}

	secretId := SecretId{Service: service, Key: k}
	tags, err := secretStore.ReadTags(cmd.Context(), secretId)
	if err != nil {
		return fmt.Errorf("Failed to read tags: %w", err)
	}

	printTags(tags)
	return nil
}

func printTags(tags map[string]string) {
	w := tabwriter.NewWriter(os.Stdout, 0, 8, 2, '\t', 0)
	fmt.Fprintln(w, "Key\tValue")
	for k, v := range tags {
		fmt.Fprintf(w, "%s\t%s\n", k, v)
	}
	w.Flush()
}

