	service, k, err := validateServiceAndKey(args[0], args[1])
	if err != nil {
		return err
	}

	tags := make(map[string]string, len(args)-2)
	for _, tagArg := range args[2:] {
		tagKey, tagValue, found := strings.Cut(tagArg, "=")
		if !found {
			return fmt.Errorf("Failed to parse tag %s: %w", tagArg, errors.New("tag must be in the form key=value"))
		}
		tags[tagKey] = tagValue
	}

	secretStore, err := getSecretStore(cmd)
	if err != nil {
		return fmt.Errorf("Failed to get secret store: %w", err)
	}

	secretId := SecretId{Service: service, Key: k}
	if err := secretStore.WriteTags(cmd.Context(), secretId, tags, deleteOtherTags); err != nil {
		return fmt.Errorf("Failed to write tags: %w", err)
	}

	printTags(tags)
	return nil
}

func tagDelete(cmd *cobra.Command, args []string) error {
	service, k, err := validateServiceAndKey(args[0], args[1])
	if err != nil {
		return err
	}

	tagKeys := make([]string, len(args)-2)
	copy(tagKeys, args[2:])

	secretStore, err := getSecretStore(cmd)
	if err != nil {
		return fmt.Errorf("Failed to get secret store: %w", err)
	}

	secretId := SecretId{Service: service, Key: k}
	if err := secretStore.DeleteTags(cmd.Context(), secretId, tagKeys); err != nil {
		return fmt.Errorf("Failed to delete tags: %w", err)
	}
	return nil
}
