package main

import (
	"errors"
	"strconv"
	"strings"
	"time"
)

// This file implements a small YAML emitter for flat string maps. The output
// mimics the style used by chamber's yaml export: double quoted scalars when
// quoting is required and literal block scalars for multi-line values.

var yamlReservedKeywords = map[string]bool{
	"null": true, "Null": true, "NULL": true, "~": true,
	"true": true, "True": true, "TRUE": true,
	"false": true, "False": true, "FALSE": true,
	"yes": true, "Yes": true, "YES": true,
	"no": true, "No": true, "NO": true,
	"on": true, "On": true, "ON": true,
	"off": true, "Off": true, "OFF": true,
	"y": true, "Y": true, "n": true, "N": true,
}

func yamlIsNumber(value string) bool {
	if len(value) == 0 {
		return false
	}
	if strings.HasPrefix(value, "_") {
		return false
	}
	dotCount := strings.Count(value, ".")
	if dotCount > 1 {
		return false
	}
	isNegative := strings.HasPrefix(value, "-")
	normalized := strings.ReplaceAll(strings.TrimPrefix(strings.TrimPrefix(value, "+"), "-"), "_", "")

	isFloat := false
	base := 10
	switch {
	case strings.HasPrefix(normalized, "0x"):
		normalized = strings.TrimPrefix(normalized, "0x")
		base = 16
	case strings.HasPrefix(normalized, "0o"):
		normalized = strings.TrimPrefix(normalized, "0o")
		base = 8
	case strings.HasPrefix(normalized, "0b"):
		normalized = strings.TrimPrefix(normalized, "0b")
		base = 2
	case strings.HasPrefix(normalized, "0") && len(normalized) > 1 && dotCount == 0:
		base = 8
	case dotCount == 1:
		isFloat = true
	}

	text := normalized
	if isNegative {
		text = "-" + text
	}

	var err error
	switch {
	case isFloat:
		_, err = strconv.ParseFloat(text, 64)
	case isNegative:
		_, err = strconv.ParseInt(text, base, 64)
	default:
		_, err = strconv.ParseUint(text, base, 64)
	}
	return err == nil || errors.Is(err, strconv.ErrRange)
}

var yamlTimeLayouts = []string{
	"2006-01-02T15:04:05Z07:00",
	"2006-01-02t15:04:05Z07:00",
	"2006-01-02 15:04:05",
	"2006-01-02",
	"15:4",
}

func yamlLooksLikeTime(value string) bool {
	for _, layout := range yamlTimeLayouts {
		if _, err := time.Parse(layout, value); err == nil {
			return true
		}
	}
	return false
}

func yamlNeedsQuote(value string) bool {
	if value == "" {
		return true
	}
	if yamlReservedKeywords[value] {
		return true
	}
	if value == "-" {
		return true
	}
	if yamlIsNumber(value) {
		return true
	}
	switch value[0] {
	case '*', '&', '[', '{', '}', ']', ',', '!', '|', '>', '%', '\'', '"', '@', ' ', '`':
		return true
	}
	switch value[len(value)-1] {
	case ':', ' ':
		return true
	}
	if yamlLooksLikeTime(value) {
		return true
	}
	for i := 0; i < len(value); i++ {
		switch value[i] {
		case '#', '\\':
			return true
		case ':', '-':
			if i+1 < len(value) && value[i+1] == ' ' {
				return true
			}
		}
	}
	return false
}

func yamlLineBreak(s string) string {
	nc := strings.Count(s, "\n")
	rc := strings.Count(s, "\r")
	rnc := strings.Count(s, "\r\n")
	switch {
	case nc == rnc && rc == rnc:
		return "\r\n"
	case rc > nc:
		return "\r"
	default:
		return "\n"
	}
}

func yamlLiteralHeader(value, lbc string) string {
	switch {
	case !strings.Contains(value, lbc):
		return ""
	case strings.HasSuffix(value, lbc+lbc):
		return "|+"
	case strings.HasSuffix(value, lbc):
		return "|"
	default:
		return "|-"
	}
}

// yamlScalar renders a string scalar. indent is the indentation of the
// enclosing mapping (0 for a top level mapping).
func yamlScalar(value string, indent int) string {
	if yamlNeedsQuote(value) {
		return strconv.Quote(value)
	}
	lbc := yamlLineBreak(value)
	if strings.Contains(value, lbc) {
		header := yamlLiteralHeader(value, lbc)
		space := strings.Repeat(" ", indent)
		lines := strings.Split(value, lbc)
		values := make([]string, 0, len(lines))
		for _, v := range lines {
			values = append(values, space+"  "+v)
		}
		block := strings.Join(values, lbc)
		block = strings.TrimSuffix(block, lbc+space+"  ")
		block = strings.TrimSuffix(block, "  "+space)
		return header + lbc + block
	}
	if len(value) > 0 && (value[0] == '{' || value[0] == '[') {
		return "'" + value + "'"
	}
	return value
}

func yamlEncodeStringMap(m map[string]string) string {
	if len(m) == 0 {
		return "{}\n"
	}
	var b strings.Builder
	for _, k := range sortedKeys(m) {
		b.WriteString(yamlScalar(k, 0))
		b.WriteString(": ")
		b.WriteString(yamlScalar(m[k], 0))
		b.WriteString("\n")
	}
	return b.String()
}
EOF
