// awsCredentials holds a set of AWS credentials
type awsCredentials struct {
	AccessKeyID     string
	SecretAccessKey string
	SessionToken    string
	CanExpire       bool
	Expires         time.Time
}

type credentialsProvider interface {
	Retrieve(ctx context.Context) (awsCredentials, error)
}

