		return ""
	}
	return p.Values[k]
}

func userHomeDir() string {
	if h := os.Getenv("HOME"); h != "" {
		return h
	}
	h, _ := os.UserHomeDir()
	return h
}

// parseINI parses an aws style ini file into sections
func parseINI(path string) (map[string]map[string]string, bool) {
	f, err := os.Open(path)
	if err != nil {
		return nil, false
	}
	defer f.Close()
	sections := map[string]map[string]string{}
	var cur map[string]string
	scanner := bufio.NewScanner(f)
	lastKey := ""
	for scanner.Scan() {
		line := scanner.Text()
		trimmed := strings.TrimSpace(line)
		if trimmed == "" || strings.HasPrefix(trimmed, "#") || strings.HasPrefix(trimmed, ";") {
			continue
		}
		if strings.HasPrefix(trimmed, "[") {
			end := strings.Index(trimmed, "]")
			if end < 0 {
				cur = nil
				continue
			}
			name := strings.TrimSpace(trimmed[1:end])
			name = strings.Join(strings.Fields(name), " ")
			if _, ok := sections[name]; !ok {
				sections[name] = map[string]string{}
			}
			cur = sections[name]
			lastKey = ""
			continue
		}
		if cur == nil {
			continue
		}
		if (line[0] == ' ' || line[0] == '\t') && lastKey != "" && !strings.Contains(trimmed, "=") {
			continue
		}
		k, v, ok := strings.Cut(trimmed, "=")
		if !ok {
			continue
		}
		k = strings.ToLower(strings.TrimSpace(k))
		v = strings.TrimSpace(v)
		cur[k] = v
		lastKey = k
	}
	return sections, true
}

func loadSharedProfile() (*sharedProfile, error) {
	name := os.Getenv("AWS_PROFILE")
	explicit := name != ""
	if name == "" {
		name = os.Getenv("AWS_DEFAULT_PROFILE")
		explicit = name != ""
	}
	if name == "" {
		name = "default"
	}

	configFile := os.Getenv("AWS_CONFIG_FILE")
	if configFile == "" {
		configFile = filepath.Join(userHomeDir(), ".aws", "config")
	}
	credsFile := os.Getenv("AWS_SHARED_CREDENTIALS_FILE")
	if credsFile == "" {
		credsFile = filepath.Join(userHomeDir(), ".aws", "credentials")
	}

	profile := &sharedProfile{Name: name, Values: map[string]string{}}
	found := false
	if sections, ok := parseINI(configFile); ok {
		var sec map[string]string
		if name == "default" {
			if s, ok := sections["default"]; ok {
				sec = s
			} else if s, ok := sections["profile default"]; ok {
				sec = s
			}
		} else {
			sec = sections["profile "+name]
		}
		if sec != nil {
			found = true
			for k, v := range sec {
				profile.Values[k] = v
			}
		}
	}
