func newHTTPClient() *http.Client {
	dialer := &net.Dialer{Timeout: 30 * time.Second, KeepAlive: 30 * time.Second}
	tr := &http.Transport{
		Proxy:                 http.ProxyFromEnvironment,
		DialContext:           dialer.DialContext,
		ForceAttemptHTTP2:     true,
		MaxIdleConns:          100,
		IdleConnTimeout:       90 * time.Second,
		TLSHandshakeTimeout:   10 * time.Second,
		ExpectContinueTimeout: 1 * time.Second,
	}
	return &http.Client{Transport: tr}
}

// loadAWSConfig mimics the default AWS configuration loading
func loadAWSConfig(ctx context.Context, maxAttempts int, retryMode string) (*awsConfig, error) {
	profile, err := loadSharedProfile()
	if err != nil {
		return nil, err
	}

	cfg := &awsConfig{
		MaxAttempts: maxAttempts,
		RetryMode:   retryMode,
		HTTPClient:  newHTTPClient(),
		Profile:     profile,
	}

	region := os.Getenv("AWS_REGION")
	if region == "" {
		region = os.Getenv("AWS_DEFAULT_REGION")
	}
	if region == "" {
		region = profile.get("region")
	}
	if v, ok := os.LookupEnv("CHAMBER_AWS_REGION"); ok {
		region = v
	}
	cfg.Region = region

	cfg.Credentials = &credentialsCache{provider: resolveCredentialsProvider(cfg)}

	if cfg.Region == "" {
		// Attempt to determine the region from the EC2 metadata service
		imds := newIMDSClient(cfg.HTTPClient)
		if r, err := imds.GetRegion(ctx); err == nil {
			cfg.Region = r
		}
	}
	return cfg, nil
}

// credentialsCache caches credentials retrieved from a provider
type credentialsCache struct {
	mu       sync.Mutex
	provider credentialsProvider
	creds    *awsCredentials
}

func (c *credentialsCache) Retrieve(ctx context.Context) (awsCredentials, error) {
	c.mu.Lock()
	defer c.mu.Unlock()
	if c.creds != nil && (!c.creds.CanExpire || time.Now().Add(10*time.Second).Before(c.creds.Expires)) {
		return *c.creds, nil
	}
	creds, err := c.provider.Retrieve(ctx)
	if err != nil {
		return awsCredentials{}, err
	}
	c.creds = &creds
	return creds, nil
}

type staticCredentials struct {
	creds awsCredentials
}

func (s *staticCredentials) Retrieve(ctx context.Context) (awsCredentials, error) {
	return s.creds, nil
}

func resolveCredentialsProvider(cfg *awsConfig) credentialsProvider {
	// Environment
	akid := os.Getenv("AWS_ACCESS_KEY_ID")
	if akid == "" {
		akid = os.Getenv("AWS_ACCESS_KEY")
	}
	secret := os.Getenv("AWS_SECRET_ACCESS_KEY")
	if secret == "" {
		secret = os.Getenv("AWS_SECRET_KEY")
	}
	if akid != "" && secret != "" {
		return &staticCredentials{creds: awsCredentials{AccessKeyID: akid, SecretAccessKey: secret, SessionToken: os.Getenv("AWS_SESSION_TOKEN")}}
	}

	// Shared profile
	p := cfg.Profile
	if p.get("aws_access_key_id") != "" && p.get("aws_secret_access_key") != "" {
		return &staticCredentials{creds: awsCredentials{
			AccessKeyID:     p.get("aws_access_key_id"),
			SecretAccessKey: p.get("aws_secret_access_key"),
			SessionToken:    p.get("aws_session_token"),
		}}
	}
	if proc := p.get("credential_process"); proc != "" {
		return &processCredentials{command: proc}
	}

	// Container credentials
	if rel := os.Getenv("AWS_CONTAINER_CREDENTIALS_RELATIVE_URI"); rel != "" {
		return &containerCredentials{client: cfg.HTTPClient, url: "http://169.254.170.2" + rel}
	}
	if full := os.Getenv("AWS_CONTAINER_CREDENTIALS_FULL_URI"); full != "" {
		return &containerCredentials{client: cfg.HTTPClient, url: full}
	}

	// EC2 instance role
	return &imdsCredentials{client: newIMDSClient(cfg.HTTPClient)}
}

func awsUserAgent(apiName, apiVersion, metrics string) string {
	ua := fmt.Sprintf("aws-sdk-go-v2/%s ua/2.1 os/%s lang/go#%s md/GOOS#%s md/GOARCH#%s api/%s#%s",
		sdkVersion, runtime.GOOS, sdkGoVersion, runtime.GOOS, runtime.GOARCH, apiName, apiVersion)
	if v := os.Getenv("AWS_EXECUTION_ENV"); v != "" {
		ua += " exec-env/" + v
	}
	if metrics != "" {
		ua += " m/" + metrics
	}
	return ua
}
