// imdsClient is a minimal EC2 instance metadata service client
type imdsClient struct {
	http          *http.Client
	endpoint      string
	disabled      bool
	mu            sync.Mutex
	tokenDisabled bool
	token         string
	tokenExpires  time.Time
}

const imdsMaxAttempts = 3

func newIMDSClient(hc *http.Client) *imdsClient {
	endpoint := os.Getenv("AWS_EC2_METADATA_SERVICE_ENDPOINT")
	if endpoint == "" {
		if strings.EqualFold(os.Getenv("AWS_EC2_METADATA_SERVICE_ENDPOINT_MODE"), "IPv6") {
