type imdsTokenFallback struct{}

func sleepCtx(ctx context.Context, d time.Duration) error {
	if d <= 0 {
		return nil
	}
	t := time.NewTimer(d)
	defer t.Stop()
	select {
	case <-ctx.Done():
		return ctx.Err()
	case <-t.C:
		return nil
	}
}

// doOnce performs a single HTTP request against IMDS
func (c *imdsClient) doOnce(ctx context.Context, method, path string, headers map[string]string) (*http.Response, []byte, error) {
	req, err := http.NewRequestWithContext(ctx, method, c.endpoint+path, nil)
	if err != nil {
		return nil, nil, &requestSendError{Err: err}
	}
	req.Header.Set("User-Agent", "aws-sdk-go-v2/"+sdkVersion+" ua/2.1 os/linux lang/go#"+sdkGoVersion+" md/GOOS#linux md/GOARCH#amd64 api/imds#1.18.0")
	for k, v := range headers {
		req.Header.Set(k, v)
	}
	resp, err := c.http.Do(req)
	if err != nil {
		if ctx.Err() != nil {
			return nil, nil, &canceledError{Err: ctx.Err()}
		}
		return nil, nil, &requestSendError{Err: err}
	}
	defer resp.Body.Close()
	body, err := io.ReadAll(resp.Body)
	if err != nil {
		return resp, nil, &requestSendError{Err: err}
	}
	if resp.StatusCode < 200 || resp.StatusCode >= 300 {
		return resp, body, &httpResponseError{StatusCode: resp.StatusCode, Err: errors.New("request to EC2 IMDS failed")}
	}
