func imdsRetryable(err error) bool {
	var se *requestSendError
	if errors.As(err, &se) {
		return true
	}
	var he *httpResponseError
	if errors.As(err, &he) {
		return he.StatusCode >= 500
	}
	return false
}

// withRetries runs fn up to imdsMaxAttempts times with a fixed one second backoff
func imdsWithRetries(ctx context.Context, op string, fn func() error) error {
	var err error
	for attempt := 1; ; attempt++ {
		err = fn()
		if err == nil {
			return nil
		}
		var ce *canceledError
		if errors.As(err, &ce) {
			return &operationError{ServiceID: "ec2imds", OperationName: op, Err: err}
		}
		if !imdsRetryable(err) {
			return &operationError{ServiceID: "ec2imds", OperationName: op, Err: err}
		}
		if attempt >= imdsMaxAttempts {
			return &operationError{ServiceID: "ec2imds", OperationName: op, Err: &maxAttemptsError{Attempt: imdsMaxAttempts, Err: err}}
		}
		if serr := sleepCtx(ctx, time.Second); serr != nil {
			return &operationError{ServiceID: "ec2imds", OperationName: op, Err: &canceledError{Err: serr}}
		}
