// getToken returns an API token, or "" when falling back to IMDSv1
func (c *imdsClient) getToken(ctx context.Context) (string, error) {
	c.mu.Lock()
	defer c.mu.Unlock()
	if c.tokenDisabled {
		return "", nil
	}
	if c.token != "" && time.Now().Before(c.tokenExpires) {
		return c.token, nil
	}
	var token string
	var ttl int
	var lastErr error
	err := imdsWithRetries(ctx, "getToken", func() error {
		resp, body, err := c.doOnce(ctx, http.MethodPut, "/latest/api/token", map[string]string{"X-Aws-Ec2-Metadata-Token-Ttl-Seconds": "300"})
		lastErr = err
		if err != nil {
			return err
		}
		token = string(body)
		ttl, _ = strconv.Atoi(resp.Header.Get("X-Aws-Ec2-Metadata-Token-Ttl-Seconds"))
		return nil
	})
	if err == nil {
		c.token = token
		c.tokenExpires = time.Now().Add(time.Duration(ttl) * time.Second)
		return token, nil
	}
	var ce *canceledError
	if errors.As(err, &ce) {
		return "", err
	}
	var se *requestSendError
	if errors.As(lastErr, &se) {
		// connection problems: permanently fall back to IMDSv1
		c.tokenDisabled = true
		return "", nil
	}
	var he *httpResponseError
	if errors.As(lastErr, &he) {
		switch {
		case he.StatusCode == 403 || he.StatusCode == 404 || he.StatusCode == 405:
			sdkLogger.Printf("WARN falling back to IMDSv1: %v", err)
			c.tokenDisabled = true
			return "", nil
		case he.StatusCode == 401 || he.StatusCode >= 500:
			return "", nil
		}
	}
	return "", fmt.Errorf("failed to get API token, %w", err)
}

// getMetadata fetches the content at the given path
func (c *imdsClient) getMetadata(ctx context.Context, op, path string) (string, error) {
	if c.disabled {
		return "", &operationError{ServiceID: "ec2imds", OperationName: op, Err: errors.New(`access disabled to EC2 IMDS via client option, or "AWS_EC2_METADATA_DISABLED" environment variable`)}
	}
	var content string
	var tokenErr error
	err := imdsWithRetries(ctx, op, func() error {
		token, err := c.getToken(ctx)
		if err != nil {
			tokenErr = err
			return err
		}
		headers := map[string]string{}
		if token != "" {
			headers["X-Aws-Ec2-Metadata-Token"] = token
		}
		_, body, err := c.doOnce(ctx, http.MethodGet, path, headers)
		if err != nil {
			return err
		}
		content = string(body)
		return nil
	})
	if err != nil && tokenErr != nil && !errors.Is(err, tokenErr) {
		return "", err
	}
	return content, err
}

// GetRegion returns the region of the instance
func (c *imdsClient) GetRegion(ctx context.Context) (string, error) {
	doc, err := c.getMetadata(ctx, "GetInstanceIdentityDocument", "/latest/dynamic/instance-identity/document")
	if err != nil {
		return "", err
	}
	var d struct {
		Region string `json:"region"`
	}
	if err := json.Unmarshal([]byte(doc), &d); err != nil {
		return "", err
	}
	return d.Region, nil
}

// imdsCredentials retrieves credentials from the instance role
type imdsCredentials struct {
	client *imdsClient
}

func (p *imdsCredentials) Retrieve(ctx context.Context) (awsCredentials, error) {
	ctx, cancel := context.WithTimeout(ctx, 5*time.Second)
	defer cancel()

	roles, err := p.client.getMetadata(ctx, "GetMetadata", "/latest/meta-data/iam/security-credentials/")
	if err != nil {
		return awsCredentials{}, fmt.Errorf("no EC2 IMDS role found, %w", err)
	}
	role := ""
	scanner := bufio.NewScanner(strings.NewReader(roles))
	if scanner.Scan() {
		role = scanner.Text()
	}
	if role == "" {
		return awsCredentials{}, fmt.Errorf("no EC2 IMDS role found")
	}

	content, err := p.client.getMetadata(ctx, "GetMetadata", "/latest/meta-data/iam/security-credentials/"+role)
	if err != nil {
		return awsCredentials{}, fmt.Errorf("failed to get %s EC2 IMDS role credentials, %w", role, err)
	}
	var resp struct {
		Code            string
		Message         string
		AccessKeyID     string `json:"AccessKeyId"`
		SecretAccessKey string
		Token           string
		Expiration      time.Time
	}
	if err := json.NewDecoder(strings.NewReader(content)).Decode(&resp); err != nil {
		return awsCredentials{}, fmt.Errorf("failed to decode %s EC2 IMDS role credentials, %w", role, err)
	}
	if resp.Code != "Success" {
		return awsCredentials{}, fmt.Errorf("failed to get %s EC2 IMDS role credentials, %w", role, &apiError{Code: resp.Code, Message: resp.Message})
	}
	expires := resp.Expiration
	if time.Now().After(expires) {
		expires = time.Now().Add(15 * time.Minute)
	}
	return awsCredentials{
		AccessKeyID:     resp.AccessKeyID,
		SecretAccessKey: resp.SecretAccessKey,
		SessionToken:    resp.Token,
		CanExpire:       true,
		Expires:         expires,
	}, nil
}

// containerCredentials retrieves credentials from the ECS container endpoint
type containerCredentials struct {
	client *http.Client
	url    string
}

func (p *containerCredentials) Retrieve(ctx context.Context) (awsCredentials, error) {
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, p.url, nil)
	if err != nil {
		return awsCredentials{}, fmt.Errorf("failed to load credentials, %w", err)
	}
	if tok := os.Getenv("AWS_CONTAINER_AUTHORIZATION_TOKEN"); tok != "" {
		req.Header.Set("Authorization", tok)
	} else if f := os.Getenv("AWS_CONTAINER_AUTHORIZATION_TOKEN_FILE"); f != "" {
		if b, err := os.ReadFile(f); err == nil {
			req.Header.Set("Authorization", strings.TrimSpace(string(b)))
		}
	}
	resp, err := p.client.Do(req)
	if err != nil {
		return awsCredentials{}, fmt.Errorf("failed to load credentials, %w", &requestSendError{Err: err})
	}
	defer resp.Body.Close()
	var out struct {
		AccessKeyID     string `json:"AccessKeyId"`
		SecretAccessKey string
		Token           string
		Expiration      *time.Time
		Code            string
		Message         string
	}
	if resp.StatusCode != 200 {
		json.NewDecoder(resp.Body).Decode(&out)
		return awsCredentials{}, fmt.Errorf("failed to load credentials, %w", &apiError{Code: out.Code, Message: out.Message})
	}
	if err := json.NewDecoder(resp.Body).Decode(&out); err != nil {
		return awsCredentials{}, fmt.Errorf("failed to load credentials, %w", err)
	}
	c := awsCredentials{AccessKeyID: out.AccessKeyID, SecretAccessKey: out.SecretAccessKey, SessionToken: out.Token}
	if out.Expiration != nil {
		c.CanExpire = true
		c.Expires = *out.Expiration
	}
	return c, nil
}

// processCredentials runs an external credential_process command
type processCredentials struct {
	command string
}

func (p *processCredentials) Retrieve(ctx context.Context) (awsCredentials, error) {
	cmd := exec.CommandContext(ctx, "sh", "-c", p.command)
	cmd.Stderr = os.Stderr
	out, err := cmd.Output()
	if err != nil {
		return awsCredentials{}, fmt.Errorf("error in credential_process, %w", err)
	}
	var resp struct {
		Version         int
		AccessKeyID     string `json:"AccessKeyId"`
		SecretAccessKey string
		SessionToken    string
		Expiration      *time.Time
	}
	if err := json.Unmarshal(out, &resp); err != nil {
		return awsCredentials{}, fmt.Errorf("parse failed of process output: %s, error: %w", out, err)
	}
	c := awsCredentials{AccessKeyID: resp.AccessKeyID, SecretAccessKey: resp.SecretAccessKey, SessionToken: resp.SessionToken}
	if resp.Expiration != nil {
		c.CanExpire = true
		c.Expires = *resp.Expiration
	}
	return c, nil
}

var _ = imdsTokenFallback{}
