		}
		return nil, c.wrapResponseError(nil, &requestSendError{Err: err})
	}
	defer httpResp.Body.Close()
	respBody, err := io.ReadAll(httpResp.Body)
	if err != nil {
		return nil, c.wrapResponseError(httpResp, &deserializationError{Err: err})
