		resp, err := c.attempt(ctx, r, attempt, maxAttempts, invocationID, parseError)
		if err == nil {
			return resp, nil
		}
		if !isRetryable(err) {
			return nil, &operationError{ServiceID: c.serviceID, OperationName: op, Err: err}
		}
		if attempt >= maxAttempts {
			return nil, &operationError{ServiceID: c.serviceID, OperationName: op, Err: &maxAttemptsError{Attempt: maxAttempts, Err: err}}
		}
		if serr := sleepCtx(ctx, backoffDelay(attempt)); serr != nil {
			return nil, &operationError{ServiceID: c.serviceID, OperationName: op, Err: &canceledError{Err: serr}}
		}
	}
