func (c *awsClient) attempt(ctx context.Context, r *awsRequest, attempt, maxAttempts int, invocationID string, parseError func(resp *awsResponse) error) (*awsResponse, error) {
	creds, err := c.cfg.Credentials.Retrieve(ctx)
	if err != nil {
		return nil, &identityError{Err: err}
	}

	base, err := c.resolveEndpoint()
	if err != nil {
		return nil, err
	}

	u := *base
	u.Path = joinURLPath(base.Path, r.Path)
	if base.RawPath != "" {
		u.RawPath = joinURLPath(base.RawPath, r.Path)
	}
	if r.RawQuery != "" {
		u.RawQuery = r.RawQuery
	} else if r.Query != nil {
		u.RawQuery = r.Query.Encode()
