	if err != nil {
		return nil, c.wrapResponseError(nil, &requestSendError{Err: err})
	}
	if r.Body != nil {
		req.ContentLength = int64(len(r.Body))
	} else {
		req.Body = nil
		req.ContentLength = 0
	}
	req.Header.Set("User-Agent", c.userAgent)
	for k, v := range r.Headers {
		req.Header.Set(k, v)
	}
	req.Header.Set("Amz-Sdk-Invocation-Id", invocationID)
	req.Header.Set("Amz-Sdk-Request", fmt.Sprintf("attempt=%d; max=%d", attempt, maxAttempts))
	if r.Body != nil && !c.s3 {
		req.Header.Set("Content-Length", fmt.Sprint(len(r.Body)))
	}

	payloadHash := sha256Hex(r.Body)
	if c.s3 {
		if r.Body == nil {
			payloadHash = emptyPayloadSHA
		}
