		}
		return nil, c.wrapResponseError(nil, &requestSendError{Err: err})
	}
	defer httpResp.Body.Close()
	respBody, err := io.ReadAll(httpResp.Body)
	if err != nil {
		return nil, c.wrapResponseError(httpResp, &deserializationError{Err: err})
	}
	resp := &awsResponse{StatusCode: httpResp.StatusCode, Header: httpResp.Header, Body: respBody}
	if httpResp.StatusCode < 200 || httpResp.StatusCode >= 300 {
		return nil, c.wrapResponseError(httpResp, parseError(resp))
	}
