func (c *awsClient) responseDeserializeError(resp *awsResponse, err error) error {
	re := &responseError{Err: &deserializationError{Err: err}, withHostID: c.s3, StatusCode: resp.StatusCode}
	if c.s3 {
		re.RequestID = resp.Header.Get("X-Amz-Request-Id")
		re.HostID = resp.Header.Get("X-Amz-Id-2")
	} else {
		re.RequestID = resp.Header.Get("X-Amzn-Requestid")
	}
	return re
}

// customEndpoint returns the custom endpoint for a service following the
// precedence used by chamber: service specific AWS env var, chamber env var,
// global AWS env var.
func customEndpoint(awsServiceEnv, chamberEnv string) string {
	ignore := strings.EqualFold(os.Getenv("AWS_IGNORE_CONFIGURED_ENDPOINT_URLS"), "true")
	if !ignore {
		if v := os.Getenv(awsServiceEnv); v != "" {
			return v
		}
	}
	if chamberEnv != "" {
		if v, ok := os.LookupEnv(chamberEnv); ok {
			return v
		}
	}
	if !ignore {
		if v := os.Getenv("AWS_ENDPOINT_URL"); v != "" {
			return v
		}
	}
	return ""
}
