package main

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"math"
	"os"
	"regexp"
	"strconv"
	"strings"
	"time"
)

const (
	// DefaultKeyID is the default alias for the KMS key used to encrypt/decrypt secrets
	DefaultKeyID = "alias/parameter_store_key"

	// ConfigKey is the key of the chamber store configuration
	storeConfigService = "_chamber"
	storeConfigKey     = "store-config"
)

// validPathKeyFormat is the format that is expected for key names inside parameter store
var validPathKeyFormat = regexp.MustCompile(`^(\/[\w\-\.]+)+$`)

var ssmModeledErrors = newModeledErrors(
	[]string{
		"InternalServerError", "InvalidFilterOption", "InvalidFilterValue", "InvalidNextToken",
		"InvalidKeyId", "ParameterNotFound", "ParameterVersionNotFound", "TooManyUpdates",
		"ParameterAlreadyExists", "ParameterLimitExceeded", "ParameterMaxVersionLimitExceeded",
		"HierarchyLevelLimitExceededException", "HierarchyTypeMismatchException",
		"IncompatiblePolicyException", "InvalidAllowedPatternException",
		"InvalidPolicyAttributeException", "InvalidPolicyTypeException",
		"ParameterPatternMismatchException", "PoliciesLimitExceededException",
		"UnsupportedParameterType",
	},
	[]string{"InvalidFilterKey", "InvalidResourceId", "InvalidResourceType", "TooManyTagsError"},
)

// StoreConfig is the configuration of a chamber store
type StoreConfig struct {
	Version      string   `json:"version"`
	RequiredTags []string `json:"requiredTags,omitempty"`
}

// SSMStore implements the Store interface for AWS SSM Parameter Store
type SSMStore struct {
	client *awsClient
}

var _ Store = &SSMStore{}

// NewSSMStoreWithRetryMode creates a new SSMStore
func NewSSMStoreWithRetryMode(ctx context.Context, numRetries int, retryMode string) (*SSMStore, error) {
	cfg, err := loadAWSConfig(ctx, numRetries, retryMode)
	if err != nil {
		return nil, err
	}
	metrics := "C,g"
	if retryMode == "adaptive" {
		metrics = "F,g"
	}
	client := &awsClient{
		cfg:         cfg,
		serviceID:   "SSM",
		signingName: "ssm",
		endpointURL: customEndpoint("AWS_ENDPOINT_URL_SSM", "CHAMBER_AWS_SSM_ENDPOINT"),
		defaultHost: func(region string) string { return "ssm." + region + "." + dnsSuffix(region) },
		userAgent:   awsUserAgent("ssm", "1.67.3", metrics),
	}
	return &SSMStore{client: client}, nil
}

func dnsSuffix(region string) string {
	switch {
	case strings.HasPrefix(region, "cn-"):
		return "amazonaws.com.cn"
	case strings.HasPrefix(region, "us-iso-"):
		return "c2s.ic.gov"
	case strings.HasPrefix(region, "us-isob-"):
		return "sc2s.sgov.gov"
	}
	return "amazonaws.com"
}

// ---- SSM API shapes ----

type ssmFilter struct {
	Key    string   `json:"Key"`
	Option string   `json:"Option,omitempty"`
	Values []string `json:"Values,omitempty"`
}

type ssmDescribeParametersInput struct {
	MaxResults       *int        `json:"MaxResults,omitempty"`
	NextToken        *string     `json:"NextToken,omitempty"`
	ParameterFilters []ssmFilter `json:"ParameterFilters,omitempty"`
}

type ssmParameterMetadata struct {
	Name             *string
	Description      *string
	LastModifiedDate *float64
	LastModifiedUser *string
	Version          *int64
}

func decodeParameterMetadata(v interface{}) (*ssmParameterMetadata, error) {
	m, err := shapeObject(v)
	if err != nil || m == nil {
		return nil, err
	}
	p := &ssmParameterMetadata{}
	for k, val := range m {
		switch k {
		case "Name":
			p.Name, err = shapeString(val, "PSParameterName")
		case "Description":
			p.Description, err = shapeString(val, "ParameterDescription")
		case "LastModifiedDate":
			p.LastModifiedDate, err = shapeTime(val)
		case "LastModifiedUser":
			p.LastModifiedUser, err = shapeString(val, "String")
		case "Version":
			p.Version, err = shapeInt64(val, "PSParameterVersion")
		case "Type":
			_, err = shapeString(val, "ParameterType")
		case "KeyId":
			_, err = shapeString(val, "ParameterKeyId")
		}
		if err != nil {
			return nil, err
		}
	}
	return p, nil
}

type ssmDescribeParametersOutput struct {
	NextToken  *string
	Parameters []*ssmParameterMetadata
}

func (o *ssmDescribeParametersOutput) decodeShape(m map[string]interface{}) error {
	var err error
	for k, v := range m {
		switch k {
		case "NextToken":
			o.NextToken, err = shapeString(v, "NextToken")
		case "Parameters":
			var l []interface{}
			l, err = shapeList(v)
			for _, item := range l {
				var p *ssmParameterMetadata
				p, err = decodeParameterMetadata(item)
				if err != nil {
					return err
				}
				if p != nil {
					o.Parameters = append(o.Parameters, p)
				}
			}
		}
		if err != nil {
			return err
		}
	}
	return nil
}

type ssmParameter struct {
	Name             *string
	Value            *string
	Version          *int64
	LastModifiedDate *float64
	Description      *string
	LastModifiedUser *string
}

func decodeParameter(v interface{}) (*ssmParameter, error) {
	m, err := shapeObject(v)
	if err != nil || m == nil {
		return nil, err
	}
	p := &ssmParameter{}
	for k, val := range m {
		switch k {
		case "Name":
			p.Name, err = shapeString(val, "PSParameterName")
		case "Value":
			p.Value, err = shapeString(val, "PSParameterValue")
		case "Version":
			p.Version, err = shapeInt64(val, "PSParameterVersion")
		case "LastModifiedDate":
			p.LastModifiedDate, err = shapeTime(val)
		case "Description":
			p.Description, err = shapeString(val, "ParameterDescription")
		case "LastModifiedUser":
			p.LastModifiedUser, err = shapeString(val, "String")
		case "Type":
			_, err = shapeString(val, "ParameterType")
		case "ARN", "DataType", "Selector", "SourceResult", "KeyId":
			_, err = shapeString(val, "String")
		}
		if err != nil {
			return nil, err
		}
	}
	return p, nil
}

type ssmParametersOutput struct {
	NextToken         *string
	Parameters        []*ssmParameter
	InvalidParameters []string
}

func (o *ssmParametersOutput) decodeShape(m map[string]interface{}) error {
	var err error
	for k, v := range m {
		switch k {
		case "NextToken":
			o.NextToken, err = shapeString(v, "NextToken")
		case "Parameters":
			var l []interface{}
			l, err = shapeList(v)
			for _, item := range l {
				var p *ssmParameter
				p, err = decodeParameter(item)
				if err != nil {
					return err
				}
				if p != nil {
					o.Parameters = append(o.Parameters, p)
				}
			}
		case "InvalidParameters":
			var l []interface{}
			l, err = shapeList(v)
			for _, item := range l {
				var s *string
				s, err = shapeString(item, "PSParameterName")
				if err != nil {
					return err
				}
				if s != nil {
					o.InvalidParameters = append(o.InvalidParameters, *s)
				}
			}
		}
		if err != nil {
			return err
		}
	}
	return nil
}

type ssmGetParametersInput struct {
	Names          []string `json:"Names"`
	WithDecryption *bool    `json:"WithDecryption,omitempty"`
}

type ssmGetParametersByPathInput struct {
