func (o *ssmListTagsOutput) decodeShape(m map[string]interface{}) error {
	l, err := shapeList(m["TagList"])
	if err != nil {
		return err
	}
	for _, item := range l {
		t, err := shapeObject(item)
		if err != nil {
			return err
		}
		if t == nil {
			continue
		}
		k, err := shapeString(t["Key"], "TagKey")
		if err != nil {
			return err
		}
		v, err := shapeString(t["Value"], "TagValue")
		if err != nil {
			return err
		}
		tag := ssmTag{}
		if k != nil {
