func boolPtr(b bool) *bool { return &b }
func intPtr(i int) *int    { return &i }

func (s *SSMStore) call(ctx context.Context, op string, in, out interface{}) error {
	return s.client.callJSON(ctx, "AmazonSSM", op, in, out, ssmModeledErrors)
}

// ---- helpers ----

func (s *SSMStore) idToName(id SecretId) string {
	return fmt.Sprintf("/%s/%s", id.Service, id.Key)
}

func basePath(name string) string {
	idx := strings.LastIndex(name, "/")
	if idx <= 0 {
		return "/"
	}
	return name[:idx]
}

func floatToTime(f *float64) time.Time {
	if f == nil {
		return time.Time{}
	}
	sec, frac := math.Modf(*f)
	return time.Unix(int64(sec), int64(math.Round(frac*1e3))*int64(time.Millisecond))
}

func strVal(s *string) string {
	if s == nil {
		return ""
	}
	return *s
}

func descriptionVersion(desc *string) int {
	if desc == nil {
		return 0
	}
	v, _ := strconv.Atoi(*desc)
	return v
}

func parameterMetaToSecretMeta(p *ssmParameterMetadata) SecretMetadata {
	return SecretMetadata{
		Created:   floatToTime(p.LastModifiedDate),
		CreatedBy: strVal(p.LastModifiedUser),
		Version:   descriptionVersion(p.Description),
		Key:       strVal(p.Name),
	}
}

func (s *SSMStore) KMSKey() string {
	fromEnv, ok := os.LookupEnv("CHAMBER_KMS_KEY_ALIAS")
	if !ok {
		return DefaultKeyID
	}
	if !strings.HasPrefix(fromEnv, "alias/") {
		return "alias/" + fromEnv
	}
	return fromEnv
}

// describeAll pages through DescribeParameters, calling fn for every page.
// fn returns true to stop.
func (s *SSMStore) describePages(ctx context.Context, input *ssmDescribeParametersInput, fn func(*ssmDescribeParametersOutput) bool) error {
	for {
		out := &ssmDescribeParametersOutput{}
		if err := s.call(ctx, "DescribeParameters", input, out); err != nil {
			return err
		}
		if fn(out) {
			return nil
		}
		if out.NextToken == nil || *out.NextToken == "" {
			return nil
		}
		input.NextToken = out.NextToken
	}
}

// ---- Store implementation ----

func (s *SSMStore) Write(ctx context.Context, id SecretId, value string) error {
	return s.write(ctx, id, value, nil)
}

func (s *SSMStore) WriteWithTags(ctx context.Context, id SecretId, value string, tags map[string]string) error {
	return s.write(ctx, id, value, tags)
}

func (s *SSMStore) write(ctx context.Context, id SecretId, value string, tags map[string]string) error {
	version := 1
	current, err := s.Read(ctx, id, -1)
	if err != nil && err != ErrSecretNotFound {
		return err
	}
	if err == nil {
		if len(tags) > 0 {
			return errors.New("tags on write only supported for new secrets")
		}
		version = current.Meta.Version + 1
	} else {
		config, err := s.readStoreConfig(ctx)
		if err != nil {
			return err
		}
		var missing []string
		for _, rt := range config.RequiredTags {
			if _, ok := tags[rt]; !ok {
				missing = append(missing, rt)
			}
		}
		if len(missing) > 0 {
			return fmt.Errorf("required tags %v are missing", missing)
		}
	}

	input := &ssmPutParameterInput{
		Description: strconv.Itoa(version),
		KeyId:       s.KMSKey(),
		Name:        s.idToName(id),
		Overwrite:   true,
		Type:        "SecureString",
		Value:       value,
	}
	if err := s.call(ctx, "PutParameter", input, nil); err != nil {
		return err
	}

	if len(tags) > 0 {
		addTags := &ssmAddTagsInput{
			ResourceId:   s.idToName(id),
			ResourceType: "Parameter",
		}
		for k, v := range tags {
			addTags.Tags = append(addTags.Tags, ssmTag{Key: k, Value: v})
		}
		if err := s.call(ctx, "AddTagsToResource", addTags, nil); err != nil {
			return err
		}
	}
	return nil
}

func (s *SSMStore) readStoreConfig(ctx context.Context) (StoreConfig, error) {
	secret, err := s.Read(ctx, SecretId{Service: storeConfigService, Key: storeConfigKey}, -1)
	if err == ErrSecretNotFound {
		return StoreConfig{Version: "1"}, nil
	}
	if err != nil {
		return StoreConfig{}, err
	}
	var config StoreConfig
	if err := json.Unmarshal([]byte(strVal(secret.Value)), &config); err != nil {
		return StoreConfig{}, fmt.Errorf("failed to unmarshal store config: %w", err)
	}
	return config, nil
}

func (s *SSMStore) Read(ctx context.Context, id SecretId, version int) (Secret, error) {
	if version == -1 {
		return s.readLatest(ctx, id)
	}
	return s.readVersion(ctx, id, version)
}

func (s *SSMStore) readLatest(ctx context.Context, id SecretId) (Secret, error) {
	name := s.idToName(id)
	out := &ssmParametersOutput{}
	if err := s.call(ctx, "GetParameters", &ssmGetParametersInput{Names: []string{name}, WithDecryption: boolPtr(true)}, out); err != nil {
		return Secret{}, err
	}
	if len(out.Parameters) == 0 {
		return Secret{}, ErrSecretNotFound
	}
	param := out.Parameters[0]

	var meta *ssmParameterMetadata
	input := &ssmDescribeParametersInput{
		ParameterFilters: []ssmFilter{{Key: "Path", Option: "OneLevel", Values: []string{basePath(name)}}},
	}
	err := s.describePages(ctx, input, func(o *ssmDescribeParametersOutput) bool {
		for _, m := range o.Parameters {
			if strVal(m.Name) == strVal(param.Name) {
				meta = m
				return true
			}
		}
		return false
	})
	if err != nil {
		return Secret{}, err
	}
	if meta == nil {
		return Secret{}, ErrSecretNotFound
	}

	return Secret{Value: param.Value, Meta: parameterMetaToSecretMeta(meta)}, nil
}

type ssmHistoryEntry struct {
	Name             *string
	Value            *string
	Description      *string
	LastModifiedDate *float64
	LastModifiedUser *string
}

type ssmHistoryOutput struct {
	NextToken  *string
	Parameters []*ssmHistoryEntry
}

func (o *ssmHistoryOutput) decodeShape(m map[string]interface{}) error {
	var err error
	for k, v := range m {
		switch k {
		case "NextToken":
			o.NextToken, err = shapeString(v, "NextToken")
		case "Parameters":
			var l []interface{}
			l, err = shapeList(v)
			for _, item := range l {
				var pm map[string]interface{}
				pm, err = shapeObject(item)
				if err != nil {
					return err
				}
				if pm == nil {
					continue
				}
				h := &ssmHistoryEntry{}
				for hk, hv := range pm {
					switch hk {
					case "Name":
						h.Name, err = shapeString(hv, "PSParameterName")
					case "Value":
						h.Value, err = shapeString(hv, "PSParameterValue")
					case "Description":
						h.Description, err = shapeString(hv, "ParameterDescription")
					case "LastModifiedDate":
						h.LastModifiedDate, err = shapeTime(hv)
					case "LastModifiedUser":
						h.LastModifiedUser, err = shapeString(hv, "String")
					case "Version":
						_, err = shapeInt64(hv, "PSParameterVersion")
					}
					if err != nil {
						return err
					}
				}
				o.Parameters = append(o.Parameters, h)
			}
		}
		if err != nil {
			return err
		}
	}
	return nil
}

func (s *SSMStore) historyPages(ctx context.Context, name string, withDecryption bool, fn func(*ssmHistoryOutput) bool) error {
	input := &ssmGetParameterHistoryInput{Name: name, WithDecryption: boolPtr(withDecryption)}
	for {
		out := &ssmHistoryOutput{}
		if err := s.call(ctx, "GetParameterHistory", input, out); err != nil {
			return err
		}
		if fn(out) {
			return nil
		}
		if out.NextToken == nil || *out.NextToken == "" {
			return nil
		}
		input.NextToken = out.NextToken
	}
}

func (s *SSMStore) readVersion(ctx context.Context, id SecretId, version int) (Secret, error) {
	var result *Secret
	err := s.historyPages(ctx, s.idToName(id), true, func(o *ssmHistoryOutput) bool {
		for _, h := range o.Parameters {
			thisVersion := descriptionVersion(h.Description)
			if thisVersion == version {
				result = &Secret{
					Value: h.Value,
					Meta: SecretMetadata{
						Created:   floatToTime(h.LastModifiedDate),
						CreatedBy: strVal(h.LastModifiedUser),
						Version:   thisVersion,
						Key:       strVal(h.Name),
					},
				}
				return true
			}
		}
		return false
	})
	if err != nil {
		return Secret{}, ErrSecretNotFound
	}
	if result == nil {
		return Secret{}, ErrSecretNotFound
	}
	return *result, nil
}

func (s *SSMStore) History(ctx context.Context, id SecretId) ([]ChangeEvent, error) {
	events := []ChangeEvent{}
	err := s.historyPages(ctx, s.idToName(id), false, func(o *ssmHistoryOutput) bool {
		for _, h := range o.Parameters {
			v := descriptionVersion(h.Description)
			events = append(events, ChangeEvent{
				Type:    getChangeType(v),
				Time:    floatToTime(h.LastModifiedDate),
				User:    strVal(h.LastModifiedUser),
				Version: v,
			})
		}
		return false
	})
	if err != nil {
		return events, ErrSecretNotFound
	}
	return events, nil
}

func getChangeType(version int) ChangeEventType {
	if version == 1 {
		return Created
	}
	return Updated
}

func (s *SSMStore) List(ctx context.Context, service string, includeValues bool) ([]Secret, error) {
	secrets := map[string]Secret{}
	input := &ssmDescribeParametersInput{
		ParameterFilters: []ssmFilter{{Key: "Path", Option: "OneLevel", Values: []string{"/" + service}}},
	}
	err := s.describePages(ctx, input, func(o *ssmDescribeParametersOutput) bool {
		for _, m := range o.Parameters {
			if !validPathKeyFormat.MatchString(strVal(m.Name)) {
				continue
			}
			meta := parameterMetaToSecretMeta(m)
			secrets[meta.Key] = Secret{Value: nil, Meta: meta}
		}
		return false
	})
	if err != nil {
		return nil, err
	}

	if includeValues {
		keys := make([]string, 0, len(secrets))
		for k := range secrets {
			keys = append(keys, k)
		}
		for i := 0; i < len(keys); i += 10 {
			end := i + 10
			if end > len(keys) {
				end = len(keys)
			}
			out := &ssmParametersOutput{}
			if err := s.call(ctx, "GetParameters", &ssmGetParametersInput{Names: keys[i:end], WithDecryption: boolPtr(true)}, out); err != nil {
				return nil, err
			}
			for _, p := range out.Parameters {
				secret := secrets[strVal(p.Name)]
				secret.Value = p.Value
				secrets[strVal(p.Name)] = secret
			}
		}
	}

	result := make([]Secret, 0, len(secrets))
	for _, v := range secrets {
		result = append(result, v)
	}
	return result, nil
}

func (s *SSMStore) ListRaw(ctx context.Context, service string) ([]RawSecret, error) {
	secrets := []RawSecret{}
	input := &ssmGetParametersByPathInput{Path: "/" + service + "/", WithDecryption: boolPtr(true)}
	for {
		out := &ssmParametersOutput{}
		if err := s.call(ctx, "GetParametersByPath", input, out); err != nil {
			return nil, err
		}
		for _, p := range out.Parameters {
			if !validPathKeyFormat.MatchString(strVal(p.Name)) {
				continue
			}
			secrets = append(secrets, RawSecret{Key: strVal(p.Name), Value: strVal(p.Value)})
		}
		if out.NextToken == nil || *out.NextToken == "" {
			break
		}
		input.NextToken = out.NextToken
	}
	return secrets, nil
}

func (s *SSMStore) ListServices(ctx context.Context, service string, includeSecretName bool) ([]string, error) {
	secrets := map[string]bool{}
	input := &ssmDescribeParametersInput{
		MaxResults:       intPtr(50),
		ParameterFilters: []ssmFilter{{Key: "Name", Option: "BeginsWith", Values: []string{"/" + service}}},
	}
	var order []string
	err := s.describePages(ctx, input, func(o *ssmDescribeParametersOutput) bool {
		for _, m := range o.Parameters {
			name := strVal(m.Name)
			var entry string
			if includeSecretName {
				entry = name
			} else {
				entry, _ = parseServiceAndKey(name)
			}
			if !secrets[entry] {
				secrets[entry] = true
				order = append(order, entry)
			}
		}
		return false
	})
	if err != nil {
		return nil, err
	}
	return order, nil
}

func (s *SSMStore) Delete(ctx context.Context, id SecretId) error {
	if _, err := s.Read(ctx, id, -1); err != nil {
		return err
	}
	return s.call(ctx, "DeleteParameter", map[string]string{"Name": s.idToName(id)}, nil)
}

func (s *SSMStore) ReadTags(ctx context.Context, id SecretId) (map[string]string, error) {
	out := &ssmListTagsOutput{}
	err := s.call(ctx, "ListTagsForResource", &ssmListTagsInput{ResourceId: s.idToName(id), ResourceType: "Parameter"}, out)
	if err != nil {
		if apiErrorCode(err) == "InvalidResourceId" {
			return nil, ErrSecretNotFound
		}
		return nil, err
	}
	tags := make(map[string]string, len(out.TagList))
	for _, t := range out.TagList {
		tags[t.Key] = t.Value
	}
	return tags, nil
}

func (s *SSMStore) WriteTags(ctx context.Context, id SecretId, tags map[string]string, deleteOtherTags bool) error {
	if deleteOtherTags {
		currentTags, err := s.ReadTags(ctx, id)
		if err != nil {
			return err
		}
		config, err := s.readStoreConfig(ctx)
		if err != nil {
			return err
		}
		var leftover []string
		for _, rt := range config.RequiredTags {
			if _, ok := currentTags[rt]; ok {
				if _, ok := tags[rt]; !ok {
					leftover = append(leftover, rt)
				}
			}
		}
		if len(leftover) > 0 {
			return fmt.Errorf("required tags %v are already present, so they must be rewritten", leftover)
		}
		var toRemove []string
		for k := range currentTags {
			if _, ok := tags[k]; !ok {
				toRemove = append(toRemove, k)
			}
		}
		if len(toRemove) > 0 {
			if err := s.DeleteTags(ctx, id, toRemove); err != nil {
				return err
			}
		}
	}

	input := &ssmAddTagsInput{ResourceId: s.idToName(id), ResourceType: "Parameter"}
	for k, v := range tags {
		input.Tags = append(input.Tags, ssmTag{Key: k, Value: v})
	}
	return s.call(ctx, "AddTagsToResource", input, nil)
}

func (s *SSMStore) DeleteTags(ctx context.Context, id SecretId, tagKeys []string) error {
	config, err := s.readStoreConfig(ctx)
	if err != nil {
		return err
	}
	var required []string
	for _, k := range tagKeys {
		for _, rt := range config.RequiredTags {
			if k == rt {
				required = append(required, k)
			}
		}
	}
	if len(required) > 0 {
		return fmt.Errorf("required tags %v may not be deleted", required)
	}
	return s.call(ctx, "RemoveTagsFromResource", &ssmRemoveTagsInput{ResourceId: s.idToName(id), ResourceType: "Parameter", TagKeys: tagKeys}, nil)
}
