        trunc = 'true' if start + PAGE < len(keys) else 'false'
        nct = '<NextContinuationToken>%d</NextContinuationToken>' % (start + PAGE) if start + PAGE < len(keys) else ''
        return (200, {'Content-Type': 'application/xml', 'x-amz-request-id': 'S3RID'}, '<?xml version="1.0" encoding="UTF-8"?>\n<ListBucketResult xmlns="http://s3.amazonaws.com/doc/2006-03-01/"><Name>%s</Name><Prefix>%s</Prefix><KeyCount>%d</KeyCount><MaxKeys>1000</MaxKeys><IsTruncated>%s</IsTruncated>%s%s</ListBucketResult>' % (bucket, prefix, len(page), trunc, contents, nct))
    full = bucket + '/' + key
