        O[full] = {'body': body.decode('utf-8', 'replace'), 'ct': headers.get('Content-Type', ''), 'meta': meta}
        save(s)
        return (200, {'ETag': '"etag"', 'x-amz-request-id': 'S3RID'}, '')
    if method == 'DELETE':
        O.pop(full, None); save(s)
        return (204, {'x-amz-request-id': 'S3RID'}, '')
    if method == 'HEAD':
        if full not in O: return (404, {'x-amz-request-id': 'S3RID'}, '')
