		defaultHost: func(region string) string { return "s3." + region + "." + dnsSuffix(region) },
		userAgent:   awsUserAgent("s3", "1.91.1", "g"),
		s3:          true,
		apiName:     "s3",
		apiVer:      "1.91.1",
		opMetrics: map[string]string{
			"GetObject":     "b,g",
			"PutObject":     "Z,g",
			"ListObjectsV2": "C,g",
		},
	}
}

func isVirtualHostableS3Bucket(bucket string) bool {
	if len(bucket) < 3 || len(bucket) > 63 {
		return false
	}
	for i, ch := range bucket {
		ok := (ch >= 'a' && ch <= 'z') || (ch >= '0' && ch <= '9') || (ch == '-' && i != 0)
		if !ok {
			return false
		}
	}
	if net.ParseIP(bucket) != nil {
		return false
	}
	return true
}

// s3EscapePath escapes an object key for use in a URL path
func s3EscapePath(key string) string {
	return uriEncode(key, false)
}

// resolveS3URL builds the request URL for an S3 request. r.Path holds the
// object key (without leading slash), r.Bucket the bucket.
func (c *awsClient) resolveS3URL(r *awsRequest) (url.URL, error) {
	var base *url.URL
	if c.endpointURL != "" {
		u, err := url.Parse(c.endpointURL)
		if err != nil {
			return url.URL{}, fmt.Errorf("resolve auth scheme: resolve endpoint: endpoint rule error, %v", err)
		}
		base = u
	} else {
		if c.cfg.Region == "" || !validHostLabel(c.cfg.Region) {
			return url.URL{}, fmt.Errorf("resolve auth scheme: resolve endpoint: endpoint rule error, Invalid region: region was not a valid DNS name.")
		}
		base = &url.URL{Scheme: "https", Host: c.defaultHost(c.cfg.Region)}
	}

	u := *base
	hostname := u.Hostname()
	virtual := isVirtualHostableS3Bucket(r.Bucket) && net.ParseIP(hostname) == nil
	basePath := strings.TrimSuffix(u.Path, "/")
	if virtual {
		u.Host = r.Bucket + "." + u.Host
		u.Path = basePath + "/" + r.Path
		u.RawPath = strings.TrimSuffix(u.EscapedPath(), "/") + "/" + s3EscapePath(r.Path)
		u.RawPath = basePath + "/" + s3EscapePath(r.Path)
	} else {
		p := basePath + "/" + r.Bucket
		rp := basePath + "/" + uriEncode(r.Bucket, true)
		if r.Path != "" || r.Query == nil {
			p += "/" + r.Path
			rp += "/" + s3EscapePath(r.Path)
		}
		u.Path = p
		u.RawPath = rp
	}
	if r.RawQuery != "" {
		u.RawQuery = r.RawQuery
	} else if r.Query != nil {
		u.RawQuery = r.Query.Encode()
	}
	return u, nil
}

type s3ErrorResponse struct {
	Code      string `xml:"Code"`
	Message   string `xml:"Message"`
	RequestID string `xml:"RequestId"`
	HostID    string `xml:"HostId"`
}

func parseS3Error(op string, resp *awsResponse) (error, string, string) {
	var e s3ErrorResponse
	code, message := "", ""
	if len(resp.Body) > 0 {
		if err := xml.Unmarshal(resp.Body, &e); err == nil {
			code, message = e.Code, e.Message
		}
	}
	if code == "" {
		text := http.StatusText(resp.StatusCode)
		code = strings.ReplaceAll(text, " ", "")
		if message == "" {
			message = text
		}
	}
	for _, m := range s3ModeledErrors[op] {
		if strings.EqualFold(m, code) {
			return &apiError{Code: m, Message: message, Modeled: true}, e.RequestID, e.HostID
		}
	}
	return &apiError{Code: code, Message: message}, e.RequestID, e.HostID
}

// s3Call performs an S3 REST call
func (c *awsClient) s3Call(ctx context.Context, op, method, bucket, key string, query url.Values, rawQuery string, headers map[string]string, body []byte) (*awsResponse, error) {
	r := &awsRequest{
		Method:   method,
		Bucket:   bucket,
		Path:     key,
		Query:    query,
		RawQuery: rawQuery,
		Headers:  map[string]string{"Accept-Encoding": "identity"},
		Body:     body,
	}
	for k, v := range headers {
		r.Headers[k] = v
	}
	if body != nil {
		sum := crc32.ChecksumIEEE(body)
		var b [4]byte
		binary.BigEndian.PutUint32(b[:], sum)
		r.Headers["X-Amz-Checksum-Crc32"] = base64.StdEncoding.EncodeToString(b[:])
	}
	return c.do(ctx, op, r, func(resp *awsResponse) error {
		err, _, _ := parseS3Error(op, resp)
		return err
	})
}

// s3GetObject fetches an object. found is false when the object does not exist.
func s3GetObject(ctx context.Context, c *awsClient, bucket, key string) ([]byte, bool, error) {
	resp, err := c.s3Call(ctx, "GetObject", "GET", bucket, key, nil, "x-id=GetObject", map[string]string{"X-Amz-Checksum-Mode": "ENABLED"}, nil)
	if err != nil {
		if apiErrorCode(err) == "NoSuchKey" {
			return nil, false, nil
		}
		return nil, false, err
	}
	if err := validateS3Checksum(resp); err != nil {
		return nil, false, &operationError{ServiceID: c.serviceID, OperationName: "GetObject", Err: err}
	}
	return resp.Body, true, nil
}

func validateS3Checksum(resp *awsResponse) error {
	if v := resp.Header.Get("X-Amz-Checksum-Crc32"); v != "" {
		sum := crc32.ChecksumIEEE(resp.Body)
		var b [4]byte
		binary.BigEndian.PutUint32(b[:], sum)
		actual := base64.StdEncoding.EncodeToString(b[:])
		if actual != v {
			return fmt.Errorf("checksum did not match: algorithm CRC32, expect %s, actual %s", v, actual)
		}
		return nil
	}
	if v := resp.Header.Get("X-Amz-Checksum-Crc32c"); v != "" {
		sum := crc32.Checksum(resp.Body, crc32.MakeTable(crc32.Castagnoli))
		var b [4]byte
		binary.BigEndian.PutUint32(b[:], sum)
		actual := base64.StdEncoding.EncodeToString(b[:])
		if actual != v {
			return fmt.Errorf("checksum did not match: algorithm CRC32C, expect %s, actual %s", v, actual)
		}
		return nil
	}
	for _, h := range []string{"X-Amz-Checksum-Sha1", "X-Amz-Checksum-Sha256", "X-Amz-Checksum-Crc64nvme"} {
		if resp.Header.Get(h) != "" {
			return nil
		}
	}
	sdkLogger.Printf("WARN Response has no supported checksum. Not validating response payload.")
	return nil
}

func s3PutObject(ctx context.Context, c *awsClient, bucket, key string, body []byte, sseHeaders map[string]string) error {
	headers := map[string]string{"Content-Type": "application/octet-stream"}
	for k, v := range sseHeaders {
		headers[k] = v
	}
	_, err := c.s3Call(ctx, "PutObject", "PUT", bucket, key, nil, "x-id=PutObject", headers, body)
	return err
}

func s3DeleteObject(ctx context.Context, c *awsClient, bucket, key string) error {
	_, err := c.s3Call(ctx, "DeleteObject", "DELETE", bucket, key, nil, "x-id=DeleteObject", nil, nil)
	return err
}

type s3ListResult struct {
	IsTruncated           bool   `xml:"IsTruncated"`
	NextContinuationToken string `xml:"NextContinuationToken"`
	Contents              []struct {
		Key string `xml:"Key"`
	} `xml:"Contents"`
}

// s3ListObjectKeys lists all object keys with the given prefix
func s3ListObjectKeys(ctx context.Context, c *awsClient, bucket, prefix string) ([]string, error) {
	var keys []string
	token := ""
	for {
		q := "list-type=2&prefix=" + url.QueryEscape(prefix)
		if token != "" {
			q = "continuation-token=" + url.QueryEscape(token) + "&" + q
		}
		resp, err := c.s3Call(ctx, "ListObjectsV2", "GET", bucket, "", url.Values{}, q, nil, nil)
		if err != nil {
			return nil, err
		}
		var res s3ListResult
		if err := xml.NewDecoder(bytes.NewReader(resp.Body)).Decode(&res); err != nil {
			return nil, &operationError{ServiceID: c.serviceID, OperationName: "ListObjectsV2", Err: c.responseDeserializeError(resp, fmt.Errorf("failed to decode response body, %w", err))}
		}
		for _, o := range res.Contents {
			keys = append(keys, o.Key)
		}
		if !res.IsTruncated || res.NextContinuationToken == "" {
			break
		}
		token = res.NextContinuationToken
	}
	return keys, nil
}
