const latestS3IndexFile = "__latest.json"

// secretObject is the format of the object stored for every secret
type secretObject struct {
	Service string                `json:"service"`
	Key     string                `json:"key"`
	Values  map[int]secretVersion `json:"values"`
}

// secretVersion is a single version of a secret
type secretVersion struct {
	Created   time.Time `json:"created"`
	CreatedBy string    `json:"created_by"`
	Version   int       `json:"version"`
	Value     string    `json:"value"`
}

// latestIndexFile is the index of the latest values of a service
