package store

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"sort"
	"time"
)

const latestS3IndexFile = "__latest.json"

// secretObject is the format of the object stored for every secret
type secretObject struct {
	Service string                `json:"service"`
	Key     string                `json:"key"`
	Values  map[int]secretVersion `json:"values"`
}

// secretVersion is a single version of a secret
type secretVersion struct {
	Created   time.Time `json:"created"`
	CreatedBy string    `json:"created_by"`
	Version   int       `json:"version"`
	Value     string    `json:"value"`
}

// latestIndexFile is the index of the latest values of a service
type latestIndexFile struct {
	Latest map[string]string `json:"latest"`
}

// S3Store implements the Store interface for S3
type S3Store struct {
	client *awsClient
	sts    *awsClient
	bucket string
}

var _ Store = &S3Store{}

// NewS3StoreWithBucket creates a new S3Store
func NewS3StoreWithBucket(ctx context.Context, numRetries int, bucket string) (*S3Store, error) {
	cfg, err := loadAWSConfig(ctx, numRetries, "standard")
	if err != nil {
		return nil, err
	}
	return &S3Store{client: newS3Client(cfg), sts: newSTSClient(cfg, ""), bucket: bucket}, nil
}

func getObjectPath(id SecretId) string {
	return fmt.Sprintf("%s/%s.json", id.Service, id.Key)
}

func getIndexPath(service string) string {
	return fmt.Sprintf("%s/%s", service, latestS3IndexFile)
}

func getLatestVersion(m map[int]secretVersion) int {
	max := 0
	for k := range m {
		if k > max {
			max = k
		}
	}
	return max
}

// readObject reads a secret object; ok is false if it does not exist
func readSecretObject(ctx context.Context, c *awsClient, bucket string, id SecretId) (secretObject, bool, error) {
	body, found, err := s3GetObject(ctx, c, bucket, getObjectPath(id))
	if err != nil {
		return secretObject{}, false, err
	}
	if !found {
		return secretObject{}, false, nil
	}
	var obj secretObject
	if err := json.Unmarshal(body, &obj); err != nil {
		return secretObject{}, false, err
	}
	return obj, true, nil
}

func readSecret(ctx context.Context, c *awsClient, bucket string, id SecretId, version int) (Secret, error) {
	obj, ok, err := readSecretObject(ctx, c, bucket, id)
	if err != nil {
		return Secret{}, err
	}
	if !ok {
		return Secret{}, ErrSecretNotFound
	}
	if version == -1 {
		version = getLatestVersion(obj.Values)
	}
	val, ok := obj.Values[version]
	if !ok {
		return Secret{}, ErrSecretNotFound
	}
	value := val.Value
	return Secret{
		Value: &value,
		Meta: SecretMetadata{
			Created:   val.Created,
			CreatedBy: val.CreatedBy,
			Version:   val.Version,
			Key:       obj.Key,
		},
	}, nil
}

func secretHistory(ctx context.Context, c *awsClient, bucket string, id SecretId) ([]ChangeEvent, error) {
	obj, ok, err := readSecretObject(ctx, c, bucket, id)
	if err != nil {
		return []ChangeEvent{}, err
	}
	if !ok {
		return []ChangeEvent{}, ErrSecretNotFound
	}
	versions := make([]int, 0, len(obj.Values))
	for v := range obj.Values {
		versions = append(versions, v)
	}
	sort.Ints(versions)
	events := []ChangeEvent{}
	for _, v := range versions {
		val := obj.Values[v]
		events = append(events, ChangeEvent{
			Type:    getChangeType(val.Version),
			Time:    val.Created,
			User:    val.CreatedBy,
			Version: val.Version,
		})
	}
	return events, nil
}

// writeSecretObject adds a new version to the secret object and stores it
func writeSecretObject(ctx context.Context, c, sts *awsClient, bucket string, id SecretId, value string, sse map[string]string) error {
	obj, ok, err := readSecretObject(ctx, c, bucket, id)
	if err != nil {
		return err
	}
	if !ok {
		obj = secretObject{
			Service: id.Service,
			Key:     fmt.Sprintf("/%s/%s", id.Service, id.Key),
			Values:  map[int]secretVersion{},
		}
	}
	if obj.Values == nil {
		obj.Values = map[int]secretVersion{}
	}
	thisVersion := getLatestVersion(obj.Values) + 1

	user, err := getCallerIdentityArn(ctx, sts)
	if err != nil {
		return err
	}

	obj.Values[thisVersion] = secretVersion{
		Version:   thisVersion,
		Value:     value,
		Created:   time.Now().UTC(),
		CreatedBy: user,
	}
	contents, err := json.Marshal(obj)
	if err != nil {
		return err
	}
	return s3PutObject(ctx, c, bucket, getObjectPath(id), contents, sse)
}

