// latestValue is an entry of a KMS index file
type latestValue struct {
	Version  int    `json:"version"`
	Value    string `json:"value"`
	KMSAlias string `json:"KMSAlias"`
}

// kmsLatestIndexFile is the index of the latest values for one KMS key
type kmsLatestIndexFile struct {
	Latest map[string]latestValue `json:"latest"`
}

// S3KMSStore implements the Store interface for S3 using KMS encryption
type S3KMSStore struct {
	S3Store
	kmsKeyAlias string
}

var _ Store = &S3KMSStore{}

// NewS3KMSStore creates a new S3KMSStore
func NewS3KMSStore(ctx context.Context, numRetries int, bucket string, kmsKeyAlias string) (*S3KMSStore, error) {
	cfg, err := loadAWSConfig(ctx, numRetries, "standard")
	if err != nil {
		return nil, err
	}
	if !strings.HasPrefix(kmsKeyAlias, "alias/") {
		kmsKeyAlias = "alias/" + kmsKeyAlias
	}
	return &S3KMSStore{
		S3Store:     S3Store{client: newS3Client(cfg), sts: newSTSClient(cfg, ""), bucket: bucket},
		kmsKeyAlias: kmsKeyAlias,
	}, nil
}

func (s *S3KMSStore) sse() map[string]string {
	return map[string]string{
		"X-Amz-Server-Side-Encryption":                "aws:kms",
		"X-Amz-Server-Side-Encryption-Aws-Kms-Key-Id": s.kmsKeyAlias,
	}
}

func getKMSIndexPath(service, alias string) string {
	return fmt.Sprintf("%s/__kms_%s__latest.json", service, strings.ReplaceAll(alias, "/", "_"))
}

// readLatestFile reads all of the KMS index files of the service and merges them
func (s *S3KMSStore) readLatestFile(ctx context.Context, service string) (kmsLatestIndexFile, error) {
	merged := kmsLatestIndexFile{Latest: map[string]latestValue{}}
	keys, err := s3ListObjectKeys(ctx, s.client, s.bucket, service+"/__kms")
	if err != nil {
		return merged, err
	}
	for _, k := range keys {
		body, found, err := s3GetObject(ctx, s.client, s.bucket, k)
		if err != nil {
			return merged, err
		}
		if !found {
			continue
		}
		var index kmsLatestIndexFile
		if err := json.Unmarshal(body, &index); err != nil {
			return merged, err
		}
		for key, v := range index.Latest {
			merged.Latest[key] = v
		}
	}
	return merged, nil
}

func (s *S3KMSStore) writeLatestFile(ctx context.Context, service string, merged kmsLatestIndexFile) error {
	index := kmsLatestIndexFile{Latest: map[string]latestValue{}}
	for k, v := range merged.Latest {
		if v.KMSAlias == s.kmsKeyAlias {
			index.Latest[k] = v
		}
	}
	contents, err := json.Marshal(index)
	if err != nil {
		return err
	}
	return s3PutObject(ctx, s.client, s.bucket, getKMSIndexPath(service, s.kmsKeyAlias), contents, s.sse())
}

func (s *S3KMSStore) checkAlias(index kmsLatestIndexFile, key string) error {
	if v, ok := index.Latest[key]; ok && v.KMSAlias != s.kmsKeyAlias {
		return fmt.Errorf("Unable to overwrite secret %s using new KMS key %s; mismatch with existing key %s", key, s.kmsKeyAlias, v.KMSAlias)
	}
	return nil
}

func (s *S3KMSStore) Write(ctx context.Context, id SecretId, value string) error {
	index, err := s.readLatestFile(ctx, id.Service)
	if err != nil {
		return err
	}
	if err := s.checkAlias(index, id.Key); err != nil {
		return err
	}
	obj, ok, err := readSecretObject(ctx, s.client, s.bucket, id)
	if err != nil {
		return err
	}
