		version = getLatestVersion(obj.Values) + 1
	}
	if err := writeSecretObjectWith(ctx, s.client, s.sts, s.bucket, id, value, s.sse(), obj, ok); err != nil {
		return err
	}
	index.Latest[id.Key] = latestValue{Version: version, Value: value, KMSAlias: s.kmsKeyAlias}
	return s.writeLatestFile(ctx, id.Service, index)
}

