#!/usr/bin/env python3
import subprocess, sys, os, json, re, time
ORIG = '/tmp/orig/executable'
NEW = '/workspace/executable'
VERBOSE = os.environ.get('CMP_VERBOSE')
def run(exe, case):
    env = dict(os.environ)
    for k in list(env):
        if k.startswith('AWS_') or k.startswith('CHAMBER_') or k.startswith('CMP_'):
            del env[k]
    env.update(case.get('env', {}))
    if case.get('pre'):
        subprocess.run(case['pre'], shell=True, env=env)
    t = time.time()
    try:
        p = subprocess.run([exe] + case['args'], input=case.get('stdin', b''), env=env, capture_output=True, timeout=case.get('timeout', 60), cwd=case.get('cwd', '/tmp'))
        out, err, rc = p.stdout, p.stderr, p.returncode
    except subprocess.TimeoutExpired as e:
        out, err, rc = e.stdout or b'', e.stderr or b'', 'TIMEOUT'
    dt = time.time() - t
    post = b''
    if case.get('post'):
        post = subprocess.run(case['post'], shell=True, env=env, capture_output=True).stdout
    filt = case.get('filter')
    if filt:
        out, err = filt(out), filt(err)
    if case.get('sort_out'):
        out = b'\n'.join(sorted(out.split(b'\n')))
    if case.get('nopost'):
        post = b''
    return (out, err, rc, post), dt
def main():
    ns = {}
    exec(open(sys.argv[1]).read(), ns)
    cases = ns['CASES']
    only = sys.argv[2:]
    fails = 0
    n = 0
    for i, c in enumerate(cases):
        name = c.get('name') or ' '.join(c['args'])
        if only and not any(o in name for o in only): continue
        n += 1
        a, da = run(ORIG, c)
        b, db = run(NEW, c)
        if VERBOSE or da > 5 or db > 5:
            print('.. [%d] %s orig %.1fs new %.1fs' % (i, name, da, db), flush=True)
        if a != b:
            fails += 1
            print('FAIL [%d] %s' % (i, name))
            for label, x, y in zip(['stdout', 'stderr', 'rc', 'post'], a, b):
                if x != y:
                    print('  %s orig: %r' % (label, x[:3000] if isinstance(x, bytes) else x))
                    print('  %s new : %r' % (label, y[:3000] if isinstance(y, bytes) else y))
            sys.stdout.flush()
    print('%d/%d failed' % (fails, n))
main()
EOF
