// annotate renders the source lines around the position
func annotate(lines []string, pos Pos, endLine int) string {
	if endLine < pos.Line {
		endLine = pos.Line
	}
	last := len(lines)
	for last > 0 && strings.TrimSpace(lines[last-1]) == "" {
		last--
	}
	var b strings.Builder
	start := pos.Line - 3
	if start < 1 {
		start = 1
	}
	for n := start; n <= endLine && n <= len(lines); n++ {
