	src  []rune
	i    int
	line int
	col  int
}

func newScanner(s string) *scanner {
	return &scanner{src: []rune(s), line: 1, col: 1}
}

func (s *scanner) eof() bool { return s.i >= len(s.src) }

func (s *scanner) peek() rune {
	if s.eof() {
		return 0
	}
	return s.src[s.i]
}

func (s *scanner) peekAt(n int) rune {
	if s.i+n >= len(s.src) || s.i+n < 0 {
		return 0
	}
	return s.src[s.i+n]
}

func (s *scanner) next() rune {
	r := s.src[s.i]
	s.i++
	if r == '\n' {
		s.line++
		s.col = 1
	} else {
