func (s *scanner) pos() Pos { return Pos{Line: s.line, Col: s.col} }

type scannerState struct {
	i, line, col int
}

func (s *scanner) save() scannerState { return scannerState{s.i, s.line, s.col} }
func (s *scanner) restore(st scannerState) {
	s.i, s.line, s.col = st.i, st.line, st.col
}

func isBlank(r rune) bool   { return r == ' ' || r == '\t' }
func isBreak(r rune) bool   { return r == '\n' || r == '\r' }
func isBlankZ(r rune) bool  { return r == 0 || isBlank(r) || isBreak(r) }
func isFlowInd(r rune) bool { return r == ',' || r == '[' || r == ']' || r == '{' || r == '}' }

