// current line
func (s *scanner) currentIndent() int {
	j := s.i - 1
	for j >= 0 && s.src[j] != '\n' {
		j--
	}
	n := 0
	for k := j + 1; k < len(s.src) && s.src[k] == ' '; k++ {
		n++
	}
	return n
}
