package yamlimport

import (
	"encoding/base64"
	"errors"
	"fmt"
	"io"
	"math"
	"strconv"
	"strings"
)

type nodeKind int

const (
	kindScalar nodeKind = iota
	kindMapping
	kindSequence
)

type node struct {
	kind    nodeKind
	pos     Pos
	endLine int
	// scalars
	raw    string
	value  string
	style  byte // 'p' plain, '\'' single, '"' double, '|' literal, '>' folded
	tag    string
	tagPos Pos
	// mappings
	pairs []pair
	// sequences
	items []*node
}

type pair struct {
	key   *node
	value *node
}

// errPanic mimics a decoder crash on some malformed flow mappings
var errPanic = errors.New("%!v(PANIC=Error method: runtime error: invalid memory address or nil pointer dereference)")

type parser struct {
	s       *scanner
	lines   []string
	anchors map[string]*node
}

func (p *parser) errorf(pos Pos, format string, args ...interface{}) error {
	return &Error{Pos: pos, Msg: fmt.Sprintf(format, args...), src: p.lines}
}

func (p *parser) errorSpan(pos Pos, endLine int, format string, args ...interface{}) error {
	return &Error{Pos: pos, EndLine: endLine, Msg: fmt.Sprintf(format, args...), src: p.lines}
}

// skipSpaces skips blanks (and comments) on the current line
func (p *parser) skipSpaces() {
	s := p.s
	for !s.eof() {
		r := s.peek()
		if r == ' ' || r == '\t' {
			s.next()
			continue
		}
		if r == '#' && (s.i == 0 || isBlankZ(s.peekAt(-1))) {
			for !s.eof() && !isBreak(s.peek()) {
				s.next()
			}
			continue
		}
		break
	}
}

// skipToContent skips blanks, comments and line breaks
func (p *parser) skipToContent() {
	s := p.s
	for !s.eof() {
		p.skipSpaces()
		if !s.eof() && isBreak(s.peek()) {
			s.next()
			continue
		}
		break
	}
}

func (p *parser) atDocumentMarker() bool {
	s := p.s
	if s.col != 1 {
		return false
	}
	for _, m := range []string{"---", "..."} {
		if s.i+3 <= len(s.src) && string(s.src[s.i:s.i+3]) == m && isBlankZ(s.peekAt(3)) {
			return true
		}
	}
	return false
}

// Decode decodes the first YAML document of src into a map of strings
func Decode(src string) (map[string]string, []string, error) {
	src = strings.TrimPrefix(src, "\ufeff")
	lines := strings.Split(strings.ReplaceAll(src, "\r\n", "\n"), "\n")
	p := &parser{s: newScanner(src), lines: lines, anchors: map[string]*node{}}
	root, err := p.parseDocument()
	if err != nil {
		return nil, nil, err
	}
	if root == nil {
		return nil, nil, io.EOF
	}
	return p.toStringMap(root)
}

func (p *parser) parseDocument() (*node, error) {
	s := p.s
	for {
		p.skipToContent()
		if s.eof() {
			return nil, nil
		}
		if s.col == 1 && s.peek() == '%' {
			for !s.eof() && !isBreak(s.peek()) {
				s.next()
			}
			continue
		}
		break
	}
	if p.atDocumentMarker() && string(s.src[s.i:s.i+3]) == "---" {
		s.next()
		s.next()
		s.next()
		p.skipSpaces()
		if !s.eof() && !isBreak(s.peek()) {
			return nil, p.errorf(s.pos(), "value cannot be placed after document separator")
		}
		p.skipToContent()
	}
	if s.eof() || p.atDocumentMarker() {
		return nil, nil
	}
	if s.peek() == '\t' {
		return nil, p.errorf(s.pos(), "found character '\t' that cannot start any token")
	}
	root, err := p.parseBlockNode(-1)
	if err != nil {
		return nil, err
	}
	p.skipToContent()
	if !s.eof() && !p.atDocumentMarker() {
		if s.peek() == '\t' {
			return nil, p.errorf(s.pos(), "found character '\t' that cannot start any token")
		}
		if root != nil && root.kind == kindMapping && root.style == 'b' {
			return nil, p.errorf(s.pos(), "non-map value is specified")
		}
		return nil, p.errorf(s.pos(), "value is not allowed in this context")
	}
	return root, nil
}

// parseProperties parses anchors and tags preceding a node
func (p *parser) parseProperties() (anchor string, tag string, tagPos Pos) {
	s := p.s
	for !s.eof() {
		r := s.peek()
		if r == '&' {
			s.next()
			start := s.i
			for !s.eof() && !isBlankZ(s.peek()) && !isFlowInd(s.peek()) {
				s.next()
			}
			anchor = string(s.src[start:s.i])
			p.skipSpaces()
			continue
		}
		if r == '!' {
			tagPos = s.pos()
			start := s.i
			for !s.eof() && !isBlankZ(s.peek()) {
				s.next()
			}
			tag = string(s.src[start:s.i])
			p.skipSpaces()
			continue
		}
		break
	}
	return
}

// parseBlockNode parses a node in block context. parentIndent is the
// indentation of the parent collection.
func (p *parser) parseBlockNode(parentIndent int) (*node, error) {
	s := p.s
	anchor, tag, tagPos := p.parseProperties()
	if anchor != "" || tag != "" {
		if s.eof() || isBreak(s.peek()) {
			// the node continues on the next line
			p.skipToContent()
			if s.eof() || s.currentIndent() <= parentIndent || p.atDocumentMarker() {
				n := &node{kind: kindScalar, pos: s.pos(), style: 'p', raw: "", tag: tag, tagPos: tagPos}
				if tag != "" {
					n.pos = tagPos
				}
				p.register(anchor, n)
				return n, nil
			}
		}
	}
	n, err := p.parseBlockNodeInner(parentIndent)
	if err != nil {
		return nil, err
	}
	if tag != "" && n != nil {
		n.tag = tag
		n.tagPos = tagPos
	}
	p.register(anchor, n)
	return n, nil
}

func (p *parser) register(anchor string, n *node) {
	if anchor != "" && n != nil {
		p.anchors[anchor] = n
	}
}

func (p *parser) parseBlockNodeInner(parentIndent int) (*node, error) {
	s := p.s
	col := s.col
	r := s.peek()
	switch {
	case r == '-' && isBlankZ(s.peekAt(1)) && !p.atDocumentMarker():
		return p.parseBlockSequence(col - 1)
	case r == '|' || r == '>':
		return p.parseBlockScalar(parentIndent)
	case r == '*':
		return p.parseAlias()
	case r == ']':
		return nil, p.errorf(s.pos(), "could not find '[' character corresponding to ']'")
	case r == '@' || r == '`':
		return nil, p.errorf(s.pos(), "'%c' is a reserved character", r)
	case r == '%':
		return nil, p.errorf(s.pos(), "unexpected directive value. document not started")
	}

	start := s.save()
	// Could this be a block mapping?
	if key, ok, err := p.tryMappingKey(); err != nil {
		return nil, err
	} else if ok {
		s.restore(start)
		_ = key
		return p.parseBlockMapping(col - 1)
	}
	s.restore(start)
	return p.parseInlineValue(parentIndent)
}

// tryMappingKey reports whether the current position starts "key:"
func (p *parser) tryMappingKey() (*node, bool, error) {
	s := p.s
	var key *node
	var err error
	r := s.peek()
	switch {
	case r == '"' || r == '\'':
		key, err = p.parseQuoted()
		if err != nil {
			return nil, false, nil
		}
	case r == '{' || r == '[':
		st := s.save()
		_, ferr := p.parseFlowNode()
		if ferr != nil {
			s.restore(st)
			return nil, false, nil
		}
		p.skipSpaces()
		if s.peek() == ':' && isBlankZ(s.peekAt(1)) {
			return nil, false, p.errorf(s.pos(), "found an invalid key for this map")
		}
		return nil, false, nil
	case r == '?' && isBlankZ(s.peekAt(1)):
		return nil, true, nil
	default:
		key = p.scanPlainKey()
		if key == nil {
			return nil, false, nil
		}
	}
	for !s.eof() && (s.peek() == ' ' || s.peek() == '\t') {
		s.next()
	}
	if s.peek() == ':' && isBlankZ(s.peekAt(1)) {
		return key, true, nil
	}
	return nil, false, nil
}

// scanPlainKey scans a plain scalar on the current line that could be a key
func (p *parser) scanPlainKey() *node {
	s := p.s
	pos := s.pos()
	start := s.i
	for !s.eof() {
		r := s.peek()
		if isBreak(r) {
			break
		}
		if r == ':' && isBlankZ(s.peekAt(1)) {
			break
		}
		if r == '#' && s.i > start && isBlank(s.peekAt(-1)) {
			break
		}
		s.next()
	}
	text := strings.TrimRight(string(s.src[start:s.i]), " \t")
	if text == "" {
		return nil
	}
	return &node{kind: kindScalar, pos: pos, raw: text, style: 'p', endLine: pos.Line}
}

func (p *parser) parseKey() (*node, error) {
	s := p.s
	anchor, tag, tagPos := p.parseProperties()
	var key *node
	var err error
	switch r := s.peek(); {
	case r == '"' || r == '\'':
		key, err = p.parseQuoted()
		if err != nil {
			return nil, err
		}
	case r == '*':
		key, err = p.parseAlias()
		if err != nil {
			return nil, err
		}
	default:
		key = p.scanPlainKey()
		if key == nil {
			key = &node{kind: kindScalar, pos: s.pos(), style: 'p'}
		}
	}
	if tag != "" {
		key.tag = tag
		key.tagPos = tagPos
	}
	p.register(anchor, key)
	return key, nil
}

func (p *parser) parseBlockMapping(indent int) (*node, error) {
	s := p.s
	m := &node{kind: kindMapping, style: 'b'}
	seen := map[string]Pos{}
	first := true
	for {
		if !first {
			p.skipToContent()
			if s.eof() || p.atDocumentMarker() {
				break
			}
			ci := s.col - 1
			if ci < indent {
				break
			}
			if ci > indent {
				return nil, p.errorf(s.pos(), "value is not allowed in this context. map key-value is pre-defined")
			}
			if s.peek() == '\t' {
				return nil, p.errorf(s.pos(), "found character '\t' that cannot start any token")
			}
			st := s.save()
			_, ok, err := p.tryMappingKey()
			if err != nil {
				return nil, err
			}
			s.restore(st)
			if !ok {
				return nil, p.errorf(s.pos(), "non-map value is specified")
			}
		}
		first = false

		explicit := false
		if s.peek() == '?' && isBlankZ(s.peekAt(1)) {
			explicit = true
			s.next()
			p.skipSpaces()
		}
		key, err := p.parseKey()
		if err != nil {
			return nil, err
		}
		if explicit {
			p.skipToContent()
		}
		p.skipSpaces()
		colonPos := s.pos()
		if s.peek() != ':' {
			return nil, p.errorf(s.pos(), "non-map value is specified")
		}
		s.next()
		if len(m.pairs) == 0 {
			m.pos = colonPos
		}
		if kstr, ok := p.keyIdentity(key); ok {
			if prev, dup := seen[kstr]; dup {
				return nil, p.errorf(key.pos, "mapping key %q already defined at [%d:%d]", kstr, prev.Line, prev.Col)
			}
			seen[kstr] = key.pos
		}

		p.skipSpaces()
		var value *node
		if s.eof() || isBreak(s.peek()) {
			// value on the following lines
			st := s.save()
			p.skipToContent()
			if !s.eof() && !p.atDocumentMarker() {
				ci := s.col - 1
				if ci > indent || (ci == indent && s.peek() == '-' && isBlankZ(s.peekAt(1))) {
					value, err = p.parseBlockNode(indent)
					if err != nil {
						return nil, err
					}
				} else {
					s.restore(st)
				}
			} else {
				s.restore(st)
			}
			if value == nil {
				value = &node{kind: kindScalar, pos: colonPos, style: 'p', raw: "null"}
				value.raw = ""
			}
		} else {
			value, err = p.parseBlockNode(indent)
			if err != nil {
				return nil, err
			}
		}
		m.pairs = append(m.pairs, pair{key: key, value: value})
	}
	return m, nil
}

func (p *parser) keyIdentity(key *node) (string, bool) {
	if key.kind != kindScalar {
		return "", false
	}
	if key.style == 'p' {
		return key.raw, true
	}
	return key.value, true
}

func (p *parser) parseBlockSequence(indent int) (*node, error) {
	s := p.s
	seq := &node{kind: kindSequence, pos: s.pos()}
	for {
		p.skipToContent()
		if s.eof() || p.atDocumentMarker() {
			break
		}
		if s.col-1 != indent || !(s.peek() == '-' && isBlankZ(s.peekAt(1))) {
			if s.col-1 > indent {
				return nil, p.errorf(s.pos(), "value is not allowed in this context")
			}
			break
		}
		s.next()
		p.skipSpaces()
		var item *node
		var err error
		if s.eof() || isBreak(s.peek()) {
			st := s.save()
			p.skipToContent()
			if !s.eof() && s.col-1 > indent {
				item, err = p.parseBlockNode(indent)
			} else {
				s.restore(st)
				item = &node{kind: kindScalar, pos: s.pos(), style: 'p'}
			}
		} else {
			item, err = p.parseBlockNode(indent)
		}
		if err != nil {
			return nil, err
		}
		seq.items = append(seq.items, item)
	}
	return seq, nil
}

func (p *parser) parseAlias() (*node, error) {
	s := p.s
	s.next()
	pos := s.pos()
	start := s.i
	for !s.eof() && !isBlankZ(s.peek()) && !isFlowInd(s.peek()) {
		s.next()
	}
	name := string(s.src[start:s.i])
	n, ok := p.anchors[name]
	if !ok {
		return nil, p.errorf(pos, "could not find alias %q", name)
	}
	return n, nil
}

// parseInlineValue parses a value that starts on the current line in
// block context (flow collection, quoted or plain scalar)
func (p *parser) parseInlineValue(parentIndent int) (*node, error) {
	s := p.s
	r := s.peek()
	var n *node
	var err error
	switch {
	case r == '{' || r == '[':
		n, err = p.parseFlowNode()
		if err != nil {
			return nil, err
		}
	case r == '"' || r == '\'':
		n, err = p.parseQuoted()
		if err != nil {
			return nil, err
		}
	case r == '|' || r == '>':
		return p.parseBlockScalar(parentIndent)
	case r == '*':
		n, err = p.parseAlias()
		if err != nil {
			return nil, err
		}
	case r == '@' || r == '`':
		return nil, p.errorf(s.pos(), "'%c' is a reserved character", r)
	case r == '%':
		return nil, p.errorf(s.pos(), "unexpected directive value. document not started")
	case r == '-' && isBlankZ(s.peekAt(1)):
		return p.parseBlockSequence(s.col - 1)
	default:
		return p.parsePlainBlock(parentIndent)
	}
	p.skipSpaces()
	if !s.eof() && !isBreak(s.peek()) {
		if s.peek() == ':' && isBlankZ(s.peekAt(1)) {
			if n.kind != kindScalar {
				return nil, p.errorf(s.pos(), "found an invalid key for this map")
			}
			return nil, p.errorf(n.pos, "mapping value is not allowed in this context")
		}
		return nil, p.errorf(s.pos(), "value is not allowed in this context. map key-value is pre-defined")
	}
	return n, nil
}

// parsePlainBlock parses a (possibly multi-line) plain scalar in block context
func (p *parser) parsePlainBlock(parentIndent int) (*node, error) {
	s := p.s
	pos := s.pos()
	var parts []string
	endLine := pos.Line
	lineText := func() (string, bool) {
		start := s.i
		for !s.eof() {
			r := s.peek()
			if isBreak(r) {
				break
			}
			if r == ':' && isBlankZ(s.peekAt(1)) {
				return string(s.src[start:s.i]), true
			}
			if r == '#' && s.i > start && isBlank(s.peekAt(-1)) {
				break
			}
			s.next()
		}
		t := strings.TrimRight(string(s.src[start:s.i]), " \t")
		p.skipSpaces()
		return t, false
	}
	t, colon := lineText()
	if colon {
		return nil, p.errorf(pos, "mapping value is not allowed in this context")
	}
	parts = append(parts, t)
	for {
		st := s.save()
		if s.eof() {
			break
		}
		// look at the next lines
		blank := 0
		s.next() // line break
		for {
			for !s.eof() && s.peek() == ' ' {
				s.next()
			}
			if !s.eof() && isBreak(s.peek()) {
				blank++
				s.next()
				continue
			}
			break
		}
		if s.eof() || s.col-1 <= parentIndent || p.atDocumentMarker() || s.peek() == '#' {
			s.restore(st)
			break
		}
		lineNo := s.line
		t, colon := lineText()
		if colon {
			return nil, p.errorSpan(pos, lineNo, "mapping value is not allowed in this context")
		}
		for i := 0; i < blank; i++ {
			parts = append(parts, "\n")
		}
		parts = append(parts, t)
		endLine = lineNo
	}
	// fold
	var b strings.Builder
	for i, part := range parts {
		if part == "\n" {
			b.WriteString("\n")
			continue
		}
		if i > 0 && parts[i-1] != "\n" {
			b.WriteString(" ")
		}
		b.WriteString(part)
	}
	return &node{kind: kindScalar, pos: pos, raw: b.String(), style: 'p', endLine: endLine}, nil
}

func (p *parser) parseQuoted() (*node, error) {
	s := p.s
	pos := s.pos()
	q := s.next()
	var b strings.Builder
	for {
		if s.eof() {
			kind := "double"
			if q == '\'' {
				kind = "single"
			}
			return nil, p.errorf(pos, "could not find end character of %s-quoted text", kind)
		}
		r := s.next()
		if q == '\'' && r == '\'' {
			if s.peek() == '\'' {
				s.next()
				b.WriteRune('\'')
				continue
			}
			break
		}
		if q == '"' && r == '"' {
			break
		}
		if q == '"' && r == '\\' {
			if s.eof() {
				continue
			}
			e := s.next()
			switch e {
			case '0':
				b.WriteRune(0)
			case 'a':
				b.WriteRune('\a')
			case 'b':
				b.WriteRune('\b')
			case 't', '\t':
				b.WriteRune('\t')
			case 'n':
				b.WriteRune('\n')
			case 'v':
				b.WriteRune('\v')
			case 'f':
				b.WriteRune('\f')
			case 'r':
				b.WriteRune('\r')
			case 'e':
				b.WriteRune(0x1b)
			case ' ':
				b.WriteRune(' ')
			case '"':
				b.WriteRune('"')
			case '/':
				b.WriteRune('/')
			case '\\':
				b.WriteRune('\\')
			case 'N':
				b.WriteRune(0x85)
			case '_':
				b.WriteRune(0xa0)
			case 'L':
				b.WriteRune(0x2028)
			case 'P':
				b.WriteRune(0x2029)
			case 'x', 'u', 'U':
				n := map[rune]int{'x': 2, 'u': 4, 'U': 8}[e]
				hex := ""
				for i := 0; i < n && !s.eof(); i++ {
					hex += string(s.next())
				}
				v, err := strconv.ParseUint(hex, 16, 32)
				if err != nil {
					return nil, p.errorf(pos, "could not find end character of double-quoted text")
				}
				b.WriteRune(rune(v))
			case '\n':
				for !s.eof() && isBlank(s.peek()) {
					s.next()
				}
			default:
				b.WriteRune('\\')
				b.WriteRune(e)
			}
			continue
		}
		if isBreak(r) {
			// line folding
			str := strings.TrimRight(b.String(), " \t")
			b.Reset()
			b.WriteString(str)
			breaks := 0
			for {
				for !s.eof() && isBlank(s.peek()) {
					s.next()
				}
				if !s.eof() && isBreak(s.peek()) {
					s.next()
					breaks++
					continue
				}
				break
			}
			if breaks == 0 {
				b.WriteRune(' ')
			} else {
				b.WriteString(strings.Repeat("\n", breaks))
			}
			continue
		}
		b.WriteRune(r)
	}
	return &node{kind: kindScalar, pos: pos, value: b.String(), style: byte(q), endLine: s.line}, nil
}

func (p *parser) parseBlockScalar(parentIndent int) (*node, error) {
	s := p.s
	pos := s.pos()
	style := byte(s.next())
	chomp := byte(0)
	explicitIndent := 0
	for !s.eof() && !isBlankZ(s.peek()) {
		r := s.next()
		switch {
		case r == '-' || r == '+':
			chomp = byte(r)
		case r >= '1' && r <= '9':
			explicitIndent = int(r - '0')
		}
	}
	p.skipSpaces()
	if !s.eof() && isBreak(s.peek()) {
		s.next()
	}
	// collect lines
	var lines []string
	indent := -1
	if explicitIndent > 0 {
		base := parentIndent
		if base < 0 {
			base = 0
		}
		indent = base + explicitIndent
	}
	endLine := pos.Line
	for !s.eof() {
		st := s.save()
		// measure indentation
		n := 0
		for !s.eof() && s.peek() == ' ' {
			s.next()
			n++
		}
		if s.eof() {
			break
		}
		if isBreak(s.peek()) {
			if indent >= 0 && n > indent {
				lines = append(lines, strings.Repeat(" ", n-indent))
			} else {
				lines = append(lines, "")
			}
			s.next()
			continue
		}
		if indent < 0 {
			if n <= parentIndent {
				s.restore(st)
				break
			}
			indent = n
		}
		if n < indent {
			s.restore(st)
			break
		}
		start := s.i
		for !s.eof() && !isBreak(s.peek()) {
			s.next()
		}
		lines = append(lines, strings.Repeat(" ", n-indent)+string(s.src[start:s.i]))
		endLine = s.line
		if !s.eof() {
			s.next()
		}
	}
	// strip trailing empty lines for chomping
	trailing := 0
	for len(lines) > 0 && lines[len(lines)-1] == "" {
		lines = lines[:len(lines)-1]
		trailing++
	}
	var content string
	if style == '|' {
		content = strings.Join(lines, "\n")
	} else {
		var b strings.Builder
		for i, l := range lines {
			if i > 0 {
				prev := lines[i-1]
				if l == "" || prev == "" || strings.HasPrefix(l, " ") || strings.HasPrefix(prev, " ") {
					b.WriteString("\n")
				} else {
					b.WriteString(" ")
				}
			}
			b.WriteString(l)
		}
		content = b.String()
		// folded: an empty line between two lines produces one newline
		content = strings.ReplaceAll(content, "\n\n", "\n")
	}
	if len(lines) > 0 {
		switch chomp {
		case '-':
		case '+':
			content += "\n" + strings.Repeat("\n", trailing)
		default:
			content += "\n"
		}
	} else if chomp == '+' {
		content = strings.Repeat("\n", trailing)
	}
	// position the scanner on the line break so that callers can continue
	if s.i > 0 && !s.eof() && s.peekAt(-1) == '\n' {
		s.i--
		s.line--
		s.col = 1
		for j := s.i - 1; j >= 0 && s.src[j] != '\n'; j-- {
			s.col++
		}
	}
	return &node{kind: kindScalar, pos: pos, value: content, style: style, endLine: endLine}, nil
}

// ---- flow ----

func (p *parser) skipFlowSpace() {
	p.skipToContent()
}

func (p *parser) parseFlowNode() (*node, error) {
	s := p.s
	anchor, tag, tagPos := p.parseProperties()
	var n *node
	var err error
	switch r := s.peek(); {
	case r == '{':
		n, err = p.parseFlowMapping()
	case r == '[':
		n, err = p.parseFlowSequence()
	case r == '"' || r == '\'':
		n, err = p.parseQuoted()
	case r == '*':
		n, err = p.parseAlias()
	default:
		n = p.parsePlainFlow()
	}
	if err != nil {
		return nil, err
	}
	if tag != "" {
		n.tag = tag
		n.tagPos = tagPos
	}
	p.register(anchor, n)
	return n, nil
}

func (p *parser) parsePlainFlow() *node {
	s := p.s
	pos := s.pos()
	start := s.i
	for !s.eof() {
		r := s.peek()
		if isBreak(r) || r == ',' || r == '[' || r == ']' || r == '{' || r == '}' {
			break
		}
		if r == ':' && (isBlankZ(s.peekAt(1)) || isFlowInd(s.peekAt(1))) {
			break
		}
		if r == '#' && s.i > start && isBlank(s.peekAt(-1)) {
			break
		}
		s.next()
	}
	text := strings.TrimRight(string(s.src[start:s.i]), " \t")
	return &node{kind: kindScalar, pos: pos, raw: text, style: 'p', endLine: pos.Line}
}

func (p *parser) parseFlowMapping() (*node, error) {
	s := p.s
	m := &node{kind: kindMapping, pos: s.pos(), style: 'f'}
	start := s.pos()
	s.next()
	seen := map[string]Pos{}
	afterComma := false
	for {
		p.skipFlowSpace()
		if s.eof() {
			if afterComma {
				return nil, errPanic
			}
			return nil, p.errorf(start, "could not find flow mapping end token '}'")
		}
		r := s.peek()
		if r == '}' {
			s.next()
			break
		}
		if r == ',' {
			s.next()
			afterComma = true
			continue
		}
		afterComma = false
		if r == ']' {
			return nil, p.errorf(s.pos(), "',' or '}' must be specified")
		}
		key, err := p.parseFlowNode()
		if err != nil {
			return nil, err
		}
		p.skipFlowSpace()
		var value *node
		if s.peek() == ':' {
			colon := s.pos()
			s.next()
			p.skipFlowSpace()
			if s.eof() {
				return nil, p.errorf(colon, "could not find map value")
			}
			if s.peek() == ',' || s.peek() == '}' {
				value = &node{kind: kindScalar, pos: colon, style: 'p'}
			} else {
				value, err = p.parseFlowNode()
				if err != nil {
					return nil, err
				}
			}
		} else if s.eof() || (s.peek() != ',' && s.peek() != '}') {
			return nil, p.errorf(key.pos, "could not find flow map content")
		} else {
			value = &node{kind: kindScalar, pos: key.pos, style: 'p'}
		}
		if key.kind != kindScalar {
			return nil, p.errorf(key.pos, "found an invalid key for this map")
		}
		if kstr, ok := p.keyIdentity(key); ok {
			if prev, dup := seen[kstr]; dup {
				return nil, p.errorf(key.pos, "mapping key %q already defined at [%d:%d]", kstr, prev.Line, prev.Col)
			}
			seen[kstr] = key.pos
		}
		m.pairs = append(m.pairs, pair{key: key, value: value})
		p.skipFlowSpace()
		if s.eof() {
			return nil, p.errorf(start, "could not find flow mapping end token '}'")
		}
		if s.peek() != ',' && s.peek() != '}' {
			return nil, p.errorf(s.pos(), "',' or '}' must be specified")
		}
	}
	m.endLine = s.line
	return m, nil
}

func (p *parser) parseFlowSequence() (*node, error) {
	s := p.s
	seq := &node{kind: kindSequence, pos: s.pos()}
	start := s.pos()
	s.next()
	for {
		p.skipFlowSpace()
		if s.eof() {
			return nil, p.errorf(start, "sequence end token ']' not found")
		}
		r := s.peek()
		if r == ']' {
			s.next()
			break
		}
		if r == ',' {
			s.next()
			continue
		}
		if r == '}' {
			return nil, p.errorf(s.pos(), "',' or ']' must be specified")
		}
		item, err := p.parseFlowNode()
		if err != nil {
			return nil, err
		}
		p.skipFlowSpace()
		if s.peek() == ':' {
			s.next()
			p.skipFlowSpace()
			if _, err := p.parseFlowNode(); err != nil {
				return nil, err
			}
		}
		seq.items = append(seq.items, item)
	}
	return seq, nil
}

// ---- conversion ----

type scalarType int

const (
	typeString scalarType = iota
	typeNull
	typeBool
	typeInt
	typeFloat
	typeInf
	typeNaN
)

type scalarValue struct {
	typ  scalarType
	str  string
	b    bool
	f    float64
	intS string // decimal representation of an int
	isI  bool   // int fits in int64/uint64
	iv   int64
}

func resolvePlain(raw string) scalarValue {
	switch raw {
	case "", "~", "null", "Null", "NULL":
		return scalarValue{typ: typeNull}
	case "true", "True", "TRUE":
		return scalarValue{typ: typeBool, b: true}
	case "false", "False", "FALSE":
		return scalarValue{typ: typeBool, b: false}
	case ".inf", ".Inf", ".INF", "+.inf", "+.Inf", "+.INF":
		return scalarValue{typ: typeInf, f: math.Inf(1)}
	case "-.inf", "-.Inf", "-.INF":
		return scalarValue{typ: typeInf, f: math.Inf(-1)}
	case ".nan", ".NaN", ".NAN":
		return scalarValue{typ: typeNaN, f: math.NaN()}
	}
	if v, ok := parseNumber(raw); ok {
		return v
	}
	return scalarValue{typ: typeString, str: raw}
}

func parseNumber(value string) (scalarValue, bool) {
	if len(value) == 0 || strings.HasPrefix(value, "_") {
		return scalarValue{}, false
	}
	dotCount := strings.Count(value, ".")
	if dotCount > 1 {
		return scalarValue{}, false
	}
	isNegative := strings.HasPrefix(value, "-")
	normalized := strings.ReplaceAll(strings.TrimPrefix(strings.TrimPrefix(value, "+"), "-"), "_", "")
	base := 10
	isFloat := false
	switch {
	case strings.HasPrefix(normalized, "0x"):
		normalized = strings.TrimPrefix(normalized, "0x")
		base = 16
	case strings.HasPrefix(normalized, "0o"):
		normalized = strings.TrimPrefix(normalized, "0o")
		base = 8
	case strings.HasPrefix(normalized, "0b"):
		normalized = strings.TrimPrefix(normalized, "0b")
		base = 2
	case strings.HasPrefix(normalized, "0") && len(normalized) > 1 && dotCount == 0:
		base = 8
	case dotCount == 1:
		isFloat = true
	}
	text := normalized
	if isNegative {
		text = "-" + text
	}
	if isFloat {
		f, err := strconv.ParseFloat(text, 64)
		if err != nil {
			if errors.Is(err, strconv.ErrRange) {
				return scalarValue{typ: typeFloat, f: f, str: value}, true
			}
			return scalarValue{}, false
		}
		return scalarValue{typ: typeFloat, f: f}, true
	}
	if isNegative {
		i, err := strconv.ParseInt(text, base, 64)
		if err != nil {
			if errors.Is(err, strconv.ErrRange) {
				return scalarValue{typ: typeInt, str: value}, true
			}
			return scalarValue{}, false
		}
		return scalarValue{typ: typeInt, intS: strconv.FormatInt(i, 10), isI: true, iv: i}, true
	}
	u, err := strconv.ParseUint(text, base, 64)
	if err != nil {
		if errors.Is(err, strconv.ErrRange) {
			return scalarValue{typ: typeInt, str: value}, true
		}
		return scalarValue{}, false
	}
	return scalarValue{typ: typeInt, intS: strconv.FormatUint(u, 10), isI: true, iv: int64(u)}, true
}

// scalarOf resolves a scalar node into a typed value
func scalarOf(n *node) scalarValue {
	var v scalarValue
	if n.style == 'p' {
		v = resolvePlain(n.raw)
	} else {
		v = scalarValue{typ: typeString, str: n.value}
	}
	text := n.raw
	if n.style != 'p' {
		text = n.value
	}
	switch n.tag {
	case "":
	case "!!str", "!":
		return scalarValue{typ: typeString, str: text}
	case "!!null":
		return scalarValue{typ: typeNull}
	case "!!bool":
		r := resolvePlain(text)
		if r.typ == typeBool {
			return r
		}
		return scalarValue{typ: typeString, str: text}
	case "!!int", "!!float":
		r := resolvePlain(text)
		if r.typ == typeInt || r.typ == typeFloat {
			if n.tag == "!!float" && r.typ == typeInt && r.isI {
				f, _ := strconv.ParseFloat(r.intS, 64)
				return scalarValue{typ: typeFloat, f: f}
			}
			return r
		}
		return scalarValue{typ: typeString, str: text}
	case "!!binary":
		b, err := base64.StdEncoding.DecodeString(strings.Join(strings.Fields(text), ""))
		if err == nil {
			return scalarValue{typ: typeString, str: string(b)}
		}
		return scalarValue{typ: typeString, str: text}
	}
	return v
}

func valueString(v scalarValue) string {
	switch v.typ {
	case typeNull:
		return ""
	case typeBool:
		return strconv.FormatBool(v.b)
	case typeInt:
		if !v.isI {
			return v.str
		}
		return v.intS
	case typeFloat:
		if v.str != "" {
			return v.str
		}
		return fmt.Sprint(v.f)
	case typeInf, typeNaN:
		return fmt.Sprint(v.f)
	}
	return v.str
}

func typeName(n *node) string {
	switch n.kind {
	case kindMapping:
		return "mapping"
	case kindSequence:
		return "sequence"
	}
	if n.tag != "" {
		return "tag"
	}
	if n.style == '|' || n.style == '>' {
		return "scalar"
	}
	if n.style != 'p' {
		return "string"
	}
	switch resolvePlain(n.raw).typ {
	case typeBool:
		return "boolean"
	case typeInt:
		return "int"
	case typeFloat:
		return "float"
	case typeInf:
		return "inf"
	case typeNaN:
		return "nan"
	case typeNull:
		return "null"
	}
	return "string"
}

func (p *parser) toStringMap(root *node) (map[string]string, []string, error) {
	if root.kind != kindMapping {
		if root.kind == kindScalar && root.style == 'p' && resolvePlain(root.raw).typ == typeNull && root.tag == "" {
			return nil, nil, io.EOF
		}
		pos := root.pos
		if root.tag != "" {
			pos = root.tagPos
		}
		return nil, nil, p.errorf(pos, "%s was used where mapping is expected", typeName(root))
	}
	out := map[string]string{}
	var order []string
	pairs := p.expandMerges(root.pairs)
	for _, pr := range pairs {
		k, err := p.keyString(pr.key)
		if err != nil {
			return nil, nil, err
		}
		v := pr.value
		switch v.kind {
		case kindMapping:
			return nil, nil, p.errorf(v.pos, "cannot unmarshal map[string]interface {} into Go value of type string")
		case kindSequence:
			return nil, nil, p.errorf(v.pos, "cannot unmarshal []interface {} into Go value of type string")
		}
		if _, ok := out[k]; !ok {
			order = append(order, k)
		}
		out[k] = valueString(scalarOf(v))
	}
	return out, order, nil
}

func (p *parser) expandMerges(pairs []pair) []pair {
	var result []pair
	for _, pr := range pairs {
		if pr.key.kind == kindScalar && pr.key.style == 'p' && pr.key.raw == "<<" && pr.key.tag == "" {
			switch pr.value.kind {
			case kindMapping:
				result = append(result, p.expandMerges(pr.value.pairs)...)
				continue
			case kindSequence:
				for _, item := range pr.value.items {
					if item.kind == kindMapping {
						result = append(result, p.expandMerges(item.pairs)...)
					}
				}
				continue
			}
		}
		result = append(result, pr)
	}
	return result
}

func (p *parser) keyString(k *node) (string, error) {
	v := scalarOf(k)
	switch v.typ {
	case typeNull:
		return "", nil
	case typeBool:
		return "", p.errorf(k.pos, "cannot convert \"bool\" type to \"string\" type")
	case typeFloat, typeInf, typeNaN:
		return "", p.errorf(k.pos, "cannot convert \"float64\" type to \"string\" type")
	case typeInt:
		if !v.isI {
			return v.str, nil
		}
		return string(rune(v.iv)), nil
	}
	return v.str, nil
}
