func sanitizeName(k string) string {
	return strings.Map(func(r rune) rune {
		if r == '-' || r == '.' || unicode.IsSpace(r) {
			return '_'
		}
		return r
	}, k)
}

// envVarName converts a secret key into an environment variable name
func envVarName(k string, preserveCase bool) string {
	n := sanitizeName(k)
	if !preserveCase {
		n = strings.ToUpper(n)
	}
	return n
}

var validShellName = regexp.MustCompile(`^[A-Za-z0-9_]+$`)

// validateShellName validates that the name is usable as a shell variable
func validateShellName(name string) error {
	if !validShellName.MatchString(name) {
		return fmt.Errorf("cmd: %q contains invalid characters for a shell variable name", name)
	}
	if name[0] >= '0' && name[0] <= '9' {
		return fmt.Errorf("cmd: shell variable name %q must start with a letter or underscore", name)
	}
	return nil
}
